(window.MUSEUM_MATCH_T = window.MUSEUM_MATCH_T || {})["zh"] = {"ui":{"lead":"名局一步一步看。一边听 Musowl 讲解，一边在棋盘上重温经典对局吧。","all":"全部","k_chess":"国际象棋","k_shogi":"将棋","k_go":"围棋","k_xiangqi":"中国象棋","side_r":"红方","res_r":"红方胜","back":"返回名局选","start":"开头","prev":"后退一步","next":"前进一步","end":"最后","play":"自动播放","pause":"暂停","moves":"棋谱","move":"第{n}步","startpos":"开始局面","nextnote":"下一条讲解（第{n}步）","quiet":"这一步没有讲解。","guide":"Musowl","keys":"← → 一步一步看","result":"结果","r_event":"对局","r_date":"年份","r_place":"地点","side_w":"白方","side_b":"黑方","side_s":"先手","side_g":"后手","side_B":"黑方","side_W":"白方","res_w":"白方胜","res_b":"黑方胜","res_d":"和棋","res_s":"先手胜","res_g":"后手胜","credit":"棋谱是公开的对局记录。讲解由博物馆的 Musowl 撰写。","caps":"提子","hand":"持驹","pnote":"上一条讲解","nnote":"下一条讲解","plies":"{n}手","about":"关于这一局"},"opera":{"t":"歌剧院之局","w":"保罗·莫菲","b":"不伦瑞克公爵卡尔二世与伊苏阿尔伯爵","ev":"在歌剧院包厢里下的一盘棋（两人商量着下）","d":"1858年","pl":"法国（巴黎）","lead":"年轻的美国冠军在歌剧演出时，对阵两位贵族，只下了17个回合。快速出子，毫不犹豫地弃子，最后只用很少的棋子取胜。这是国际象棋书里最常出现的一盘棋。","c":{"0":"1858年的巴黎。21岁的美国人保罗·莫菲接连击败了欧洲的强手。那天晚上，在歌剧院的包厢里，布伦瑞克公爵和伊苏阿尔伯爵两人一边商量一边执黑，向莫菲挑战。据说莫菲还想看舞台上的演出，所以想早点结束。这17个回合里装满了国际象棋的基本道理：快速出子，让王安全。","1":"白方把王前的兵走两格。它盯住中央的d5和e5，也为象和后打开了路。","2":"黑方也走e5。两个兵在中央面对面，白兵不能再往前走了。","3":"马出到f3，攻击e5的兵。一边出子，一边让对方不得不防守，是好棋。","4":"黑方走d6保护e5。这叫菲利多尔防御。很稳，但f8象的路变窄了一点。","5":"白方走d4，又一个兵来到中央，冲击e5。黑方必须决定是吃还是守。","6":"黑象到g4，牵制f3的马。马后面是d1的白后，马一走后就会被吃，所以马不能去吃e5。","7":"白方用兵吃e5。如果黑方马上用d6兵吃回，白方会换后，然后马就能吃掉e5的兵。所以黑方想先除掉f3的马。","8":"黑方用象吃马，这样就能安全地吃回e5了。但刚出动的象换掉了马，黑方的出子落后了。","9":"白方用后吃回。白后已经在中央附近活跃起来，而黑方几乎还没有出子。","10":"黑方用兵吃回，子力相等。但从出动的棋子数来看，白方领先。","11":"象到c4，和f3的后一起瞄准f7。f7只有王在保护，是弱点；被吃掉就是将死。","12":"黑方把马出到f6，挡住f线。没有这一步，后吃f7就是将死。一边出子一边防守，是正确的应对。","13":"后转到b3，同时攻击f7和b7。同时有两个威胁的棋很强，因为对方没法两边都守住。","14":"黑方把后走到e7保护f7，放弃了b7。但这样后挡住了f8象的路。","15":"莫菲没有吃b7的兵，而是出马。吃兵会让后跑得太远。选择快速出子而不是多吃一个兵，正是莫菲的风格。","16":"黑方走c6，控制d5和b5，也给后打开了去b6的路。","17":"象到g5，牵制f6的马。马一走，后面e7的后就会被吃。黑方的棋子越来越难动了。","18":"黑方走b5，想赶走c4的象。这也在后翼抢到了空间，但同时给白方的棋子留下了冲进来的空隙。","19":"弃马吃b5的兵！莫菲没有让象逃走，而是继续进攻。黑王还在中间，这对黑方非常危险。","20":"黑方吃掉马，多了一个马。但黑王还在e8，白方的棋子不断聚集过来。","21":"象到b5将军！黑王还困在中间。白方用一个马换来两个兵，直接逼近黑王。","22":"黑方用马在d7垫将。但这个马被牵制了，一动黑王就会被将军。白方接下来就瞄准d7。","23":"白方长易位。王安全了，同时车来到d1瞄准d7。一步棋同时完成防守和进攻，非常出色。","24":"黑方把车出到d8保护d7。黑方还不能易位，h8的车和f8的象完全没有发挥作用。","25":"弃车吃d7！白方送出一个车，除掉黑方的一个防守棋子。","26":"黑方用车吃回。现在d7的车也被牵制了，一动b5的象就会将军黑王。","27":"另一个车也来到d1，再次攻击d7。现在攻击d7的白子比防守的黑子还多。","28":"黑后到e6，提议换后，想把b3的白后赶走，也想帮忙保护d7。但已经来不及了。","29":"象吃d7并将军。白方把黑方的防守棋子一个一个地除掉。","30":"黑方用马吃回。f6的马离开了，从g5的象到d8的斜线通了。这条斜线在最后会起作用。","31":"后弃在b8并将军！这是这盘棋最有名的一步。黑方只能用马吃，马一离开d7，d线就打开了。","32":"黑方用马吃。现在已经没有黑子保护d8了。","33":"车到d8，将死！g5的象支援d8，黑王被自己的棋子围住，无处可逃。白方送出了后、车和象，最后只用一个车和一个象结束了对局。快速出子、让王安全、趁对方的王还在中间一口气进攻——这盘最有名的名局包含了所有这些重要的道理。"}},"reti1910":{"t":"列蒂杀法","w":"理查德·列蒂","b":"萨维利·塔尔塔科维尔","ev":"一盘随意下的棋（不是比赛）","d":"1910年","pl":"奥地利（维也纳）","lead":"两位后来的大师在维也纳随意下的一盘棋，只有11个回合。白方弃掉后，用两个棋子同时将军的\"双将\"一举取胜。这种杀法以白方的名字命名，叫做\"列蒂杀法\"。","c":{"0":"1910年的维也纳。白方是20岁的理查德·列蒂，黑方是萨维利·塔尔塔科维尔。两人后来都成了世界顶尖棋手，也以给国际象棋带来新思路而闻名。这不是比赛，而是押了一点小钱的随意对局。虽然很短，却能清楚看出\"早点让王安全\"有多重要。","1":"白方把王前的兵走两格。占住中央，后面的棋子就容易出动。象和后的路也打开了。","2":"黑方走c6。不马上进中央，而是为下一步d5冲击e4的兵做准备。这种稳固的开局叫卡罗-康防御。","3":"白方把另一个兵也走到d4。两个兵并排站在中央，白方占了很大空间。黑方要想办法拆掉它们。","4":"按计划走d5，向e4的兵发出\"我能吃你\"的挑战。白方要决定是保护、前进还是交换。","5":"白方出马保护e4。一边出子一边防守，一点也不浪费。","6":"黑方吃掉e4的兵。交换中心兵，让白方的中心变小。","7":"白方用马吃回来，马站到了棋盘中央。中央的马能照顾很多格子，是很强的棋子。","8":"黑方出马，和e4的马面对面。这里常见的是象出到f5，但黑方选择邀请换马。","9":"白后早早来到d3，保护e4的马。一般来说后不要出得太早，但白方另有打算。请记住，这个后站在d线上，正对着黑王前方。","10":"黑方走e5，送出一个兵，为象和后打开通路。这是在中央挑起战斗的积极一步。","11":"白方吃掉e5的兵。白方收下了礼物，但这也让黑后更容易活动。","12":"将军！a5的黑后沿斜线瞄准e1的王，同时还打算吃回e5的兵，一步两用。白方必须挡住。","13":"白方把象放在d2挡住将军。后可以吃这个象，但白后好好地保护着它。","14":"黑方吃回了兵，子力又相等了。而且这个后沿e线正对着e4的马和后面的王。马一走开王就会被将军，所以马动不了。看起来黑方马上就能吃掉它。","15":"白方长易位。王离开了e线，马又能自由行动了。同时车来到d1：d1的车、d3的后和黑王旁边的d8排成一条线。这就是白方的陷阱。","16":"黑方吃掉e4的马，好像多得了一个子。但黑王还在e8，也没有易位。白方的棋子都排在d线上，黑王身边空荡荡的。这一步导致了失败，是胜负的分水岭。","17":"后走到d8将军！把最强的棋子白白送掉。能吃它的黑子只有王。让对方吃，就是为了把王拉到d8这个危险的格子上。","18":"黑方只能用王吃，没有别的办法挡将。王被拉到了d8，后面还有d1的车在等着。","19":"象从d2走到g5将军，同时让开了后面d1车的路，车也沿d线将军。两个棋子同时将军叫\"双将\"。双将既不能靠吃掉一个子解除，也不能垫子挡住，王只能逃。","20":"王逃到c7。如果逃到e8，车走到d8就是将死。不管王逃到哪里，白方都准备好了致命一击。","21":"象走到d8，沿斜线将死c7的王！象由d1的车保护，王吃不了它。b8、c8、b7、c6等格子被黑方自己的棋子堵住，d6和d7被车控制。只用11个回合，白方弃后，用两个小子取胜。这盘棋告诉我们：不易位就去吃子，王会有多危险。也有记录说黑方在前一步就认输了。"}},"immortal":{"t":"不朽之局","w":"阿道夫·安德森","b":"莱昂内尔·基塞里茨基","ev":"1851年伦敦大赛期间下的一盘非正式对局","d":"1851年","pl":"英国（伦敦）","lead":"世界上第一次国际比赛在伦敦举行时，两人在休息时下了这盘棋。白方先后弃掉象、两个车，最后连后也弃掉，只用剩下的三个小子将死对方。据说黑方中途就认输了，最后几步可能是白方演示的走法。","c":{"0":"1851年6月，伦敦。这一年，世界上第一次国际象棋国际大赛正在伦敦举行。白方是德国的数学老师阿道夫·安德森，黑方是在巴黎“摄政咖啡馆”教棋的莱昂内尔·基塞里茨基。这不是大赛的正式对局，而是在休息时轻松下的一盘棋。基塞里茨基把棋谱登在自己办的杂志上传开，后来这盘棋被称为“不朽之局”。让我们来看看这场接连弃子进攻、很有那个时代特色的战斗吧。Musowl 为你讲解。","1":"白方把王前的兵向前走两格。它看住了中心的d5和f5两格，象和后的通路也打开了。不管过去还是现在，这都是最常见的第一步。","2":"黑方同样走e5。两个兵正面相对，黑方也不让出中心。黑方的象和后也有了通路。","3":"f4！白方白白送出一个兵，这就是“王翼弃兵”。黑方如果吃掉它，黑方e5的兵就离开了中心，白方也更容易把兵推到d4。在这个时代，这种尽早发起进攻的作战非常流行。不过它的弱点是，白王前面会被打开。","4":"黑方接受了这个兵。f4的兵挡住了白方c1象的道路，还盯着e3和g3两格。黑方多了一个兵。","5":"白方把象走到c4。黑王旁边的f7只有王在保护，是个弱点。白方瞄准那里，随时可以发动攻击。","6":"将军！因为白方走了f兵，从h4到e1的斜线打开了。白方如果走g3来挡，也会被f4的兵吃掉。白方只能移动王。","7":"王向旁边躲一格到f1。这样白方就再也不能王车易位，没法把王安全地藏起来了。不过黑后出来得太早，白方接下来可以一边出子一边追赶黑后。","8":"黑方也白白送出一个兵。用b5把c4的象引开，让它离开瞄准f7的斜线。这步棋后来被称为“布赖恩反弃兵”，是基塞里茨基喜欢用的进攻手段。","9":"白方吃掉这个兵。象离开了c4，就不再瞄准f7了。不过白方也吃回一个兵，双方子力又相等了。","10":"黑方的马跳到f6。它攻击e4的兵，也能保护王的周围，是个好位置。出子的比赛开始了。","11":"白方也把马跳到f3。一边出子一边威胁h4的黑后，这是非常舒服的一步。黑后必须逃走，白方等于多赚了一步。","12":"黑后退到h6。从这里它盯着h线，还看着白方h2兵后面h1的车。这里暂时还是安全的。","13":"用d3牢牢保护受到攻击的e4兵。同时也为c1的象打开了通路。这是稳健、没有浪费的一步。","14":"黑马跳到h5。它保护f4的兵，下一步打算跳到g3。马跳到g3会将军并攻击h1的车；白方如果用h2兵吃马，h线就打开了，h6的黑后就能吃掉h1的车。这是相当犀利的计划。","15":"白马跳到h4。这匹马挡住了h线，所以即使黑马跳到g3，h1的车也不会被吃了。而且它还准备下一步跳到f5，威胁h6的黑后。","16":"黑后走到g5，攻击h4的马。白方必须决定是保护这匹马，还是把它移到别处。","17":"马跳到f5。有e4的兵保护，这是非常强的位置。从这里它攻击g7的兵，还盯着h6和d6两格。白方的棋子正在逼近黑王。","18":"黑方用c6想赶走b5的象。如果象逃走，黑方就能用兵扩大中心。这是普通而合理的一步。","19":"可是白方不救象，而是走g4！威胁h5的马。即使丢掉一个象，也要追赶黑方的棋子，为进攻争取时间，这是个大胆的想法。g4的兵由d1的后斜着保护。","20":"被攻击的马从h5退回f6。黑方认为吃白象可以晚一点再说。c6的兵仍然攻击着b5的象。","21":"车走到g1。它保护g4的兵，准备在g线上作战。b5的象仍然放着让黑方吃。白方认为，追赶黑后比一个象更重要。","22":"黑方吃掉了象。在子力上，黑方多了整整一个象，领先很多。但是除了后和一匹马，黑方的棋子都还在原来的格子里。白方的进攻从这里开始。","23":"h4！白方用兵追赶g5的黑后。白方只是推进兵，就让黑后能站的地方越来越少。","24":"黑后逃到g6。它还有几格可走，但已经开始被白方的兵和马包围了。","25":"白方用h5再次追赶黑后。白兵每前进一步，黑后就只能后退。","26":"黑后回到g5。h6被f5的马盯着，其他格子也被堵住了，几乎只剩这里可去。黑后正在一步步被逼到角落。","27":"白后走到f3。下一步如果c1的象吃掉f4的兵，g5的黑后就会受到攻击，几乎无处可逃。这是设下陷阱、要捉住黑后的一步。","28":"黑方把马退回g8，为黑后空出逃路f6。好不容易出动的马又回到原来的格子，这说明黑方开始困难了。在出子的比赛中，白方已经遥遥领先。","29":"象吃掉f4的兵，一边吃回一个兵，一边追赶g5的黑后。白方的象也终于加入了战斗。","30":"黑后逃到事先空出的f6。从这里它斜着一直看到b2的兵，还能瞄准后面a1的车。","31":"白马跳到c3。c3的马也挡住了从f6的黑后到b2的斜线。下一步它打算跳到d5，威胁f6的黑后。","32":"黑方把象走到c5，攻击g1的车。黑方终于也出动了象，加入进攻。是去吃子，还是保护王？这对黑方来说是很重要的时刻。","33":"马跳到d5！它威胁f6的黑后，还有跳到c7、同时攻击王和车的手段。但是马离开了c3，从黑后到b2的路又打开了。白方既不保护g1的车，也不保护b2的兵。即使让对方吃子，也要进攻黑王。","34":"黑后吃掉b2的兵，接着瞄准a1的车。黑方想多吃子，用子力数量取胜。但是黑后离自己的王越来越远了。","35":"象走到d6！这样白方就让两个车都任由黑方吃掉。作为交换，这个象控制了f8和e7，堵住了黑王的逃路。白方选择的不是子力多少，而是编织一张捉住黑王的网。这里是胜负的分水岭。","36":"黑方吃掉了g1的车。现在黑方多了一个象和一个车。不过，后来的研究认为，这里另一步棋更好，黑方本来有更强的防守。","37":"e5！一步安静的兵步，却是决定胜负的关键之一。这个兵挡住了从b2的黑后到g7的斜线，还控制了f6。黑后再也回不来救王，g8的马也不能跳到f6了。白方接下来威胁走用马吃g7将军，再把象走到c7将杀。","38":"黑方一边将军，一边吃掉另一个车。从a1到f1，第一横线全都空着。黑方吃掉了两个车，子力上大大领先。","39":"王躲到e2。白方剩下的大子只有后，另外是两匹马和一个象。即便如此，在黑王的周围，白方的棋子比黑方多得多。","40":"黑方把马走到a6，保护c7。这是为了阻止马吃g7将军、王逃到d8、再用象走c7将杀的手段。据说基塞里茨基在这附近就认输了，之后的着法是白方摆给大家看的。","41":"马吃掉g7的兵，将军！g7的马攻击e8的黑王。d6的象控制着e7和f8，所以王能逃的地方很少。","42":"黑王只能逃到d8。它已经不能留在e8，也去不了e7和f8，剩下的只有d8。","43":"把后弃在f6，将军！连最后一个大子也白白送出。它从f6经过e7斜着将到d8，黑方只能吃掉这个后。","44":"黑方用g8的马吃掉白后。王没有地方可逃，所以没有别的着法。但正是这匹马离开，将杀的形状才完成了。","45":"象走到e7。将杀！d5的马控制着e7和c7，g7的马控制着e8，c8和d7被黑方自己的棋子堵住。白方弃掉了一个象、两个车，甚至还有后，只用三个小子就赢了。黑方明明还剩下后和两个车，却一个也来不及帮忙。它告诉我们，棋子发挥了多大作用，比棋子的数量更重要。这是国际象棋历史上最有名的对局之一。据说这个名字是几年后由奥地利名手法尔克贝尔起的。"}},"mimiaka":{"t":"耳赤之局","w":"本因坊秀策","b":"井上幻庵因硕","ev":"大坂对局（下了三天）","d":"1846年","pl":"日本（大坂）","lead":"17岁的秀策（四段）挑战当时顶尖棋手之一幻庵（八段）。中盘秀策下出第127手时，据说幻庵的耳朵红了，因此称为“耳赤之局”。那时没有贴目，黑胜2目。","c":{"0":"1846年（弘化三年），大坂。黑方是17岁的秀策（四段），白方是48岁左右的井上幻庵因硕（八段）。幻庵曾与本因坊丈和争夺名人棋所之位，是当时顶尖棋手之一。前一天按段位差，秀策放两子开局，但幻庵很快认可了他的实力，将那盘打挂；这一局改为秀策不放子执黑。那时没有贴目，胜负只看盘上的地。让我们一手一手地看这盘下了三天的棋。","1":"黑1下在右上小目（R16）。既容易取角地，又方便向边上展开，是均衡的位置。秀策执黑时喜欢下小目。","2":"白2下在左上小目（D17）。布局先下角，因为角上最容易围地。双方分占空角。","3":"黑3下在右下小目（Q3），与右上R16方向配合，以后可以充分利用两角之间的右边。","4":"白4（P17）挂右上黑角。如果让黑再补一手，右上会非常坚固，所以白先下手。黑可以应，也可以脱先去别的大场。","5":"黑5不应，转而下左下小目（C4）。1、3、5手三个角都下小目，是秀策执黑常见的下法。对右上白P17的应对留到以后。","6":"白6（C14）下在左边。通常会挂左下黑角，但幻庵与左上白D17配合，在左边布阵。这手稍显少见，目的是先阻止黑C4向左边扩展。","7":"黑7（E4）守角，左下基本成为黑地。在白挂角之前先守住，也减少了白6在左边发挥的余地。","8":"白8（R5）挂右下黑Q3。右边上下都有黑的小目，白需要在右边找个立足点。右下的长期战斗由此开始。","9":"黑9（Q15）守右上。在白P17下方落子加固角部，同时把白P17逼向狭窄的上边。黑希望把右边留给自己。","10":"白10（O4）是“大斜”：从稍远处斜着罩住黑子。自古有“大斜百变”之说，变化极多，而这正是幻庵的拿手好戏。17岁的秀策如何应对对手最擅长的武器，是本局看点。","11":"黑11（Q5）紧贴白R5，接受战斗。本可以老实防守，但秀策选择了变化多的下法。接下来是双方计算力的较量。","12":"白12（Q4）挤进黑子之间，企图把黑Q3和Q5分断，削弱其中一块。","15":"黑13（P4）、15（P3）把下方黑子牢牢连在一起。白14（R4）钻进角里，右下角的实地成了争夺焦点。黑宁可让出一点角地，也优先把棋连好、走强。","17":"白16（P5）、黑17（Q6），双方棋子向上延伸。黑向右边出头，白从上方压住，不让黑出来。","19":"白18（R3）在角上补一子做活，黑19（O3）压住下边的白子。黑的作战是把右下角让给白，换取在下边和右边外侧的强大。","20":"白20（P6）从上方压住黑Q6的头，想把黑封在右边低处。如果黑不能向上出头，右边黑棋只能苟活，收获很小。","21":"黑21（Q7）、23（Q8）沿右边向上爬，寻找出路；白22（P7）并排压住。沿三线长长延伸的黑棋位置低、地不多，但已经活得很安稳。","24":"白24（N4）从外面封住下边黑O3、P3。黑子分成右边和下边两个方向，要同时兼顾变得困难。","25":"黑25（N3）在下边长出一路。后来的研究认为这里用征子的另一种下法更好，因此被视为本局黑的小失误。下边黑子仍然低、容易被包围，给了白反击的机会。即使是秀策，在对手擅长的定式里也有迷失的时候。","26":"白26（P8）压住右边黑棋的头。黑在右边无法向上出头，在下边也快被封住。","28":"白28（M3）紧贴下边黑N3，是严厉的一手。阻止黑在下边扩展，夺取其活动空间，同时让黑不断加子。幻庵立刻抓住了黑25的小漏洞。","30":"黑29（M2）之后，白30（L2）再从下面绕过来。黑下边的子既不能向外也不能向旁边出去，要活只能与右下角相连，围绕角部的争夺由此开始。","31":"黑31（M4）是重要的一手。不急于进入角上的战斗，先制造白必须应的地方，为接下来必然发生的劫争提前做准备。","33":"黑33（R2），右下角的对杀终于开始。白32（L3）之后下边白棋已经安全，黑只能去吃角上的白子。吃得掉，下边黑子就活；吃不掉，下边黑子就危险。","35":"白34（S2）、黑35（S1），在角上一线、二线展开细腻的交锋。双方都在紧对方的气，争取先吃掉对方。","36":"白36（N2）。开劫之前，白先在黑下边棋子周围下一手。即使黑打赢劫，所得也会小一些，是时机恰当的一手。","40":"白40（R1）提黑一子，终于形成劫。劫的规则是：被提的一方不能马上提回。黑必须先在别处下一手白必须应的棋（劫材），白应了之后才能提回。谁的劫材多，谁就占上风。","41":"黑41（O5）是第一个劫材。白若不理，右下白棋会陷入困境，所以白42（N5）应。接着黑43（R2）提回。虽然有点亏，但此时是必要的一手。","44":"白44（S7）是白的劫材，下在右边黑子旁边，逼黑45（S8）应，然后白46（R1）提回。每找一次劫材，盘上各处的棋形就确定一些。","47":"黑47（M5）、白48（N6）、黑49（R2）。黑又找劫材并提回。在下边白子周围，黑在外侧一点点增加棋子。","50":"白50（R7）切入右边黑子，是很大的劫材。通常黑会应，但黑选择优先解决劫争。结果形成大转换：白在右边得利，黑得到右下角。","51":"黑51（P2）提白一子，打赢了劫。右下角成为黑的活棋实地，下边黑子也得救了。作为交换，白接着52（R8），要把右边黑子分成两块。","53":"黑53（R10）是一般人想不到的妙手。从白子的另一侧接应被分断的右边上方黑子。如果黑老实地应，右边会被白大量占去。","56":"白54（S10）、黑55（S11）、白56（S9）。白在右边边缘做活，黑从上方压住，守住了右边的上半部。","59":"黑57（M6）、白58（N7）之后，黑59（R11）把右边黑子牢牢连上。黑右边从上到下都安全了。至此的大转换大致两分。","60":"白60（S3）是大棋。在右下角旁削减黑地，同时加强白子，还使白接下来的62（M1）成为黑必须应的先手。","63":"白62（M1）提黑一子，黑63（O1）粘上，右下的长期战斗告一段落。结果白在下边取得实地，黑在右边筑起厚势。由于黑25的小失误，此时一般认为白下得较好。但秀策的厚势之后将在中央大显身手。","65":"白64（G3）向下边左侧展开，想进一步扩大下边阵地。黑65（G5）在其上方落子，阻止白地向上扩张。“白取实地、黑取外势”的格局越来越明显。","66":"白66（C9）下在左边，与白6（C14）配合，在左边也形成白阵。白在下边和左边一点点积累实地。","67":"黑67（L17）下在上边。背靠右边厚势，意图从上边到中央形成黑的大模样（可能成为实地的广阔区域），同时夹击右上白P17。","69":"白68（J17）进入黑L17左侧，想把上边黑模样一分为二。黑69（Q17）紧贴右上白P17，一边攻击白一边加固角部。","70":"白70（O10）下在黑右边厚势与上边模样之间，阻止黑模样向中央连成一片，同时想与右边白子取得联络。","72":"白72（P13）是妙手。在黑厚势正上方落子，在黑模样中心建立白的据点。即使黑去追，白也能轻灵脱身。黑在上边的美梦因这一手而缩小了。","73":"黑73（P12）堵住白P13的下方，阻止它与右边白子相连。白74（Q18）进入右上角，也来削减黑的角地。","77":"黑75（R18）守角后，白76（O13）、黑77（N11）。黑压住白中央棋子的头，想一边攻击一边扩大自己的地。从这里到第100手左右，幻庵下得一丝不苟，不断化解黑的攻击。","79":"白78（N10）把中央白子连上，黑79（O16）巩固上边黑棋。黑虽然没能借攻击获得大利，但稳稳守住了上边的地。","80":"白80（Q12）、82（Q13），白紧贴黑右边厚势把棋子连起来。白在黑模样中做出了稳固的形，右上黑地不会像预期那么大。","83":"黑83（H3）打入下边白地。白地过大，黑要在里面落子尽量削减。白84（H2）、黑85（J2），在白地中展开是做活还是逃出的细致战斗。","87":"白86（J3）、黑87（H4）、白88（K2）。黑把打入的子与上方的G5连起来，逃了出去。白下边的地被削减，黑在中央增加了厚势。","89":"黑89（F17）逼近左上白D17，在上边左侧也落下黑子，阻止白沿上边扩展。白90（M17）、92（N17）则想在上边黑子之间做活白子。","93":"黑93（M18）、95（N16），黑从上下夹住上边白子。白只能在一、二线的低处做活，即使活了地也很小。","96":"从白96（R14）开始，在右上黑角旁展开细致的战斗。白切入黑右边厚势与右上角之间，想削弱黑子。黑97（Q14）应，白98（R12）、100（S12）沿右边边缘推进。","101":"黑101（T12）、103（T13）下到右边一线，压缩白子的做活空间。一线的棋看似小，却关系到棋子的死活。","104":"白104（Q10）冲击黑右边厚势的薄弱处。黑105（Q11）、白106（P11）之后，黑107去吃这块白子。","107":"黑107（P10）提白一子，黑右边厚势牢牢连成一片，安全了。白108（O11）、110（P9）向中央出头，保护靠近黑厚势的白子。","112":"从白112（L18）开始，上边白子急于做活。黑113（K18）、115（K17）、117（K19）将其包围，不让它向外逃。","118":"白118（M19）提黑一子，上边白棋活了。白在黑的上边模样中做活，黑地大大减少。到这里，幻庵下得非常出色。","120":"黑119（D18）试探左上白角，白120（C17）应。黑的目的不是吃角，而是巩固上边左侧，为增加黑地创造机会。","122":"黑121（F15）整理了从上边到中央的黑形。白122（C6）下在左下黑角旁边，一点点削减黑地。","124":"黑123（G2）、白124（J1）、黑125（F3），下边左侧的边界也确定了。白在下边提一子，稳稳守住了实地。","126":"白126（J5）。下边白棋很厚，准备向中央扩张。白有下边、左边的实地和右上的活棋，在地上领先。据说旁观的棋手大多认为白好。黑若按部就班地下，将追不上。","127":"这就是著名的“耳赤之手”——黑127（K11）。据说棋盘正中的这一子同时作用于四个方向：向上扩大黑模样，向下阻止白厚势伸向中央，向右支援黑厚势，向左阻挡白的扩张。一手棋做了四件事，堪称“一石四鸟”。原本被认为白好的局面，从这一手开始逐渐向黑倾斜。","128":"第127手落下时，在旁观战的一位医生注意到幻庵的耳朵红了。据说他不太懂棋，却把这看作心神动摇的表现，说“黑大概会赢”。在职业棋手们都认为白好的时候，只有医生的眼睛捕捉到了胜负的转折点。白128（E18）守左上角。","131":"黑129（F18）巩固上边左侧后，黑131（D10）打入左边白阵。因为127那颗子撑住了中央，黑可以放心地去破坏白地。","136":"黑133（E10）、135（D12），左边黑子穿过白子之间，形成活形。白136（J10）出到中央，想削弱127那颗子的作用。白也不能把中央拱手让给黑。","140":"黑137（H7）罩在下边白子上方，白138（G10）、140（F8）想在中央左侧把白子连起来。中央黑白交错，双方都有弱点。","143":"白142（E2）钻进左下黑角。黑143（D7）、145（D6）一边盯着左边白子和角里的白子，一边把黑子连起来。","147":"黑147（K10）从127那颗子直接向下延伸，把中央白子分成左右两块。127这一子在这里终于开始显示真正的威力。","150":"白148（K9）、黑149（L9）、白150（J11）。白想连接中央的子，黑切断它与下边白子的联系。白150紧挨着127那颗子，也来侵入黑的中央。","155":"从黑151（J9）到黑155（K12），黑在中央夹击白子。黑155在127那颗子上方连上，使黑中央的子与上边黑棋连成一体。黑在中央掌握了主动。","160":"白156（C5）、黑157（D5）之后，白158（J12）、160（H8）。白一边守护中央的子，一边瞄准左下黑子的弱点。胜负依然细微，双方都不能松懈。","162":"黑161（B8）钻到左边白子下面。白162（D13）压住左边黑子的头，让它们难受。","167":"黑163（G12）、165（J13）巩固中央之后，黑167（C2）是守护左下角的准确一手。如果这里脱先，白142（E2）就可能威胁角部。黑先消除危险，形成不易输的局面。","169":"白166（E17）、168（F16）在左上切黑子。黑169（G16）、171（G17）把上边黑子牢牢连上应对。","175":"黑175（G4）提白一子。黑子在下边白地中生存下来，白地并没有起初看起来那么大。差距正在一点点缩小。","180":"白176（M11）、黑177（L13）、白178（J6）、黑179（M10）、白180（M13）。在中央右侧，白也在黑模样里落子，尽量削减黑地。黑一边应对，一边把整个中央收为己地。","187":"从黑183（K13）到187（M14），黑从上方压住进入中央的白子，不让它与上边连通。白拼命想在中央做活，但黑的包围很厚，对白来说是艰苦的战斗。","195":"从白190（G14）到194（M9），白扩大中央棋子的生路。黑195（L10）切入中央白子之间，破坏白的棋形。","199":"黑199（K7），中央战斗平息。中央白棋总算活了，但黑在战斗中增加了实地，形势已向黑倾斜。接下来是确定边界的“官子”，一目两目都要争。","208":"黑203（E19）、205（F2）、白208（R19），盘边的官子从大到小依次进行。官子中，先下对方必须应的先手棋很重要。","212":"白212（D19）、216（F19）在上边边缘提掉黑子；黑也以213（G11）、217（G19）在别处找回。双方寸步不让。","225":"黑225（L6）提白一子，在下边中部黑也一点点削减白地。最后的大争夺——中央的劫——就要来了。","228":"白228（N12）提黑一子，中央形成劫。此后80多手，双方在M13和N13反复提子。每次找劫材，盘上各处都会发生小的转换。决定胜负的漫长劫争开始了。","236":"白236（T8）是在劫争中提一子的手。后来有研究认为，若在此消劫，差距会更小。漫长的劫争中，选择哪种转换会左右最后的一两目。","262":"白262（T1）、266（S4）在右下角提掉黑子。在找劫材的过程中，黑也在别处找回，双方得失交错，劫争仍在继续。","275":"黑275（T14）提白两子，右上边缘的这次转换黑得利。把劫争中的转换加起来，黑仍保持着微弱的领先。","299":"黑299（J16）一举提掉白四子。上边白的企图落空，黑上边安全了。黑渡过了劫争最后的大难关。","311":"黑311（M13）终于消劫。持续了80多手的中央劫争结束了。经历了劫争中的种种转换，黑始终守住了领先。剩下的只是收完小官子。","321":"从黑317（N1）到321（M2），下边最后的边界确定下来。双方为多争一目，直到最后都下得很准确。","325":"325手终局，数子结果黑胜2目。开局在幻庵拿手的大斜中黑稍有失误，到中盘为止一般认为白好。秀策凭第127手那一子扭转局势，又挺过漫长的劫争，守住了微弱的优势。据说幻庵后来评价：此时秀策的棋力不下于七段。这一局让秀策声名远扬，他后来成为本因坊家的继承人。开局的大斜、第127手的耳赤之手、最后的长劫——这三处就是这盘名局的看点。"}},"evergreen":{"t":"常青之局","w":"阿道夫·安德森","b":"让·杜弗雷纳","ev":"一盘随意下的棋（不是比赛）","d":"1852年","pl":"德国（据认为是柏林）","lead":"下出\"不朽之局\"的安德森，第二年又下出了这盘名局。就在黑方要将死白方的时候，白方安静地走了一步车，然后弃后，用双将结束对局。因为它永远不会褪色，所以叫做\"常青之局\"。","c":{"0":"1852年，德国。白方是前一年赢得伦敦大赛冠军、被认为是世界最强棋手的阿道夫·安德森。黑方是他的朋友让·杜弗雷纳，他后来写了一本很多人读过的国际象棋入门书。这不是大赛，而是一盘轻松的对局，地点被认为是柏林，但没有明确的记录。它是在“不朽之局”的第二年诞生的另一盘名局。据说后来的冠军斯坦尼茨称赞它是“安德森桂冠上的常青叶”，这个名字由此而来。让我们和 Musowl 一起来看吧。","1":"白方把王前的兵向前走两格。它看住了中心的d5和f5，象和后的道路也打开了。","2":"黑方同样走e5。在中心和白兵面对面，毫不退让。","3":"白方把马跳到f3。一边出子，一边攻击黑方e5的兵。黑方必须保护这个兵。","4":"黑方把马跳到c6，保护e5的兵。一边出子一边防守，没有浪费。","5":"白方把象走到c4，瞄准黑王旁边的f7。f7只有王在保护，是个弱点。","6":"黑方同样把象走到c5，瞄准白方的f2。双方形状一样，到这里是非常平静的开局。","7":"b4！白方白白送出一个兵，这就是“埃文斯弃兵”。据说这是英国一位叫埃文斯的船长想出的作战，在这个时代非常流行。黑方如果用象吃掉，白方就推进c3、d4，一边赢得时间，一边占领中心。","8":"黑方用象吃掉这个兵。这是收下送来的东西的一步，但因为象动了，白方接下来可以抢先追赶它。","9":"用c3威胁b4的象。同时这也是为下一步d4做准备。","10":"象退到a5。从a5可以斜着一直看到e1，从侧面瞄准c3的兵。","11":"d4！白方把兵推进中心。它冲击黑方e5的兵，想把棋盘中央变成白方的地盘。白方的棋子可以一个接一个地出动了。","12":"黑方吃掉d4的兵。黑方多了两个兵。不过黑方还没有王车易位，出动的棋子也还很少。","13":"白方王车易位。把王安全地放进角落，车也很快能参加战斗。即使少了两个兵，白方在出子速度上也遥遥领先。","14":"黑方走d3。兵向前一格，在白方阵地里打进一个楔子。这个兵成了妨碍白方棋子行动的一根小刺。这个局面里其他着法也被研究得很多，但黑方选择了有点特别的一步。","15":"白后走到b3。它和c4的象一起瞄准f7，形成可怕的阵势。f7只有王在保护，所以用象吃f7将军的手段越来越严厉了。","16":"黑方把后走到f6，保护f7。黑后一边保护f7，一边也盯着白方的王翼，是个很有作用的位置。","17":"e5！用兵赶走黑后。这个兵还堵住了黑马跳到f6的路，让黑方的棋子很局促。","18":"黑后逃到g6。从这里它沿着g线瞄准白王前面的g2，还盯着e4这一格。","19":"车走到e1，牢牢保护e5的兵。白方的车也加入了战斗。","20":"黑方把马跳到e7。接下来黑方想王车易位，让王安全。马没有跳到f6而是跳到e7，是因为f6被e5的兵控制着。","21":"象走到a3！从a3到f8有一条笔直的斜线。这个象瞄准e7的马，也盯着它后面的f8。如果马一动，到f8的路就打开了，所以黑方很难在王翼易位了。这是把黑王关在中间的非常重要的一步。","22":"黑方用b5送出一个兵，威胁c4的象。这是想把白后从f7引开、进行骚扰的反击。","23":"白方用后吃掉这个兵。白后一边保护c4的象，一边继续瞄准黑王附近。","24":"黑车走到b8，威胁b5的白后。车开始在打开的b线上发挥作用了。","25":"白后走到a4。它攻击a5的象，同时沿着从a4到e8的斜线，把c6的马牵制在黑王身上。这匹马一动，王就会被将军，所以它不能动。","26":"象从a5逃到b6。它回到了原来瞄准f2方向的斜线上。","27":"白方把马跳到d2。最后一个留在家里的棋子也出动了，下一步打算跳到e4，靠近黑王。","28":"黑方把象走到b7，保护被牵制的c6马。从b7出发的长斜线现在被c6的马挡住，但如果马一动，这个象就能瞄准f3和g2的方向。","29":"马跳到e4！从棋盘中央，它威胁跳到f6或d6将军。黑王还在中间，很危险。","30":"黑后走到f5，同时盯着e4的马和f3的马。想让马让开，再去进攻白王。","31":"象吃掉d3的兵。成为黑方之刺的兵没有了。而且这个象从e4马的后面看着f5的黑后：只要马一动，象就能吃掉黑后。","32":"黑后逃到h5。从这里它经过g4瞄准f3的马。计划是下一步用后吃f3，再利用g线将杀白王。","33":"马跳到f6将军！同时还攻击h5的黑后，这是一步双击。为了不丢后，黑方决定吃掉这匹马。","34":"黑方用g7的兵吃掉马。g线打开了，黑方可以用g8的车瞄准白王了。","35":"白方用e5的兵吃回f6。这个兵威胁e7的马，而且因为e线打开了，e1的车隔着e7的马看着黑王。f6的兵还控制着g7和e7两格。","36":"黑车走到g8。在打开的g线上瞄准白王前面的g2。如果下一步黑后吃掉f3，g2就会同时受到后和车的攻击，黑方似乎就能将杀白方了。","37":"车走到d1！黑方有将杀的威胁，白方却安静地走了一步车。从d1到d7之间只有d3的象。只要象一动，车就会直接盯着黑王旁边的格子。这是一步想用连续将军抢先取胜的、算得很深的棋，也是这盘棋最有名的一步。不过，后来的研究认为，白方和黑方都还有别的着法，到今天仍在研究中。","38":"黑后吃掉f3的马。下一步只要吃g2，再配合车就是将杀。白方现在只能靠连续将军来取胜了。","39":"车吃掉e7的马，将军！即使弃子，白方也要继续追赶黑王。","40":"黑方用c6的马吃回。可是马离开了c6，从a4的白后到d7的斜线就打开了。据说即使黑方不用马吃、而是让王逃走，白方的攻势也会继续。","41":"把后弃在d7，将军！白后穿过刚刚打开的斜线，直接冲到黑王面前。这就是“常青之局”的决定性一击。","42":"黑方用王吃掉白后。如果逃到f8，白后就会吃掉e7的马将杀，所以只能吃。","43":"象走到f5，双将！象从f5将d7的黑王，象让开之后，d1的车也沿着d线将军。两个棋子同时将军时，不能靠垫子或吃子来防守，王只能逃走。","44":"黑王逃到e8。如果逃到c6，象走到d7就是将杀。","45":"象走到d7将军。这一次它就在e8黑王的旁边。这个象有d1的车保护，所以黑王不能吃它。","46":"黑王走到f8。如果逃到d8，a3的象吃掉e7的马也是将杀。","47":"a3的象吃掉e7的马，将杀！d7的象控制e8，f6的兵控制e7和g7，f7和g8被黑方自己的棋子堵住。f6的兵、走到a3之后一直没动的象、d1的车，所有棋子在最后都完美地发挥了作用。黑方用后和车瞄准g2，却差了一步没赶上。看清对手的意图，再用连续将军抢先取胜，这是一盘堪称进攻范本的对局。"}},"lasker1912":{"t":"猎王之局","w":"爱德华·拉斯克","b":"乔治·艾伦·托马斯","ev":"在伦敦城国际象棋俱乐部下的一盘快棋（随意的对局）","d":"1912年","pl":"英国（伦敦）","lead":"在伦敦一家俱乐部里下的一盘随意的快棋。白方弃后，把黑王从g8一路赶到g1，横穿整个棋盘。各种记录里开局的顺序稍有不同，但第10回合后的局面是一样的。","c":{"0":"1912年10月，伦敦城国际象棋俱乐部。白方是刚从德国来的年轻工程师爱德华·拉斯克，黑方是后来成为英国冠军的乔治·艾伦·托马斯。这是一盘时间很短、很随意的快棋。它以\"猎王\"闻名：黑王从g8一路被赶到棋盘另一端的g1。拉斯克后来去了美国，因写国际象棋书而广为人知。","1":"白方先走d4，后前的兵。它控制e5和c5，也给c1的象让出了路。","2":"黑方走e6，先摆出稳固的形状，准备下一步走f5或d5。","3":"马到f3。它控制e5，也帮助保护王翼，是最自然的位置。","4":"黑方走f5，控制e4格，接近荷兰防御。但王前的兵动了，黑王周围变得有点弱。","5":"另一个马也到c3，准备走e4去冲击f5的兵。","6":"黑方也把马出到f6，进一步控制e4，同时准备易位。","7":"象到g5，瞄准f6的马。这个马是保护黑王的重要棋子，所以白方想早点除掉它。","8":"黑方把象出到e7保护马，易位的准备也更进一步。","9":"白方用象换掉马。保护黑王的马不见了。","10":"黑方用象吃回。现在f6的象接过了保护王翼的任务。","11":"e4！冲击f5的兵，扩大中心。线路打开，白方的棋子更容易活动。","12":"黑方吃掉e4的兵。不吃的话，白方会走e5把黑方的棋子赶回去。","13":"马吃回来站到中央，盯着f6的象以及g5、d6格。","14":"黑方走b6，准备把象出到b7，从长斜线瞄准e4的马。","15":"马到e5，这是中央的好格子，也盯着g4和f7。白方的两个马都靠近了黑方王翼。","16":"黑方王车易位，王到了g8。但f线的兵不在了，王周围有很多空隙。","17":"象到d3。现在被自己e4的马挡住，但再往前就是h7的兵。e4的马一动，这个象就会直指h7。","18":"黑象到b7，从长斜线瞄准e4的马，让白方的棋子不太自由。","19":"后到h5，瞄准h7的兵。h7只有黑王保护。白方的后、象和马全都对准了黑王。","20":"黑方把后走到e7。它保护f6的象，也准备去c5，但黑方没发现白方的意图。这里应该走h6或吃掉e5的马。这是胜负的分水岭。","21":"后弃在h7并将军！把最强的棋子白白送掉。拉斯克已经看清了一路追王直到将死的路线。","22":"黑方只能用王吃。王被拉到了h7。","23":"马吃掉f6的象并将军。同时e4空了出来，d3的象也将军h7的王：双将。双将挡不住，王只能逃。","24":"王到h6。如果退到h8，另一个马跳到g6就是将死。王被越赶越往前。","25":"另一个马从e5跳到g4将军。它攻击h6的王，把王继续往前赶。","26":"王到g5，离开了自己的阵地，向白方那边走去。","27":"用h兵将军！连兵也加入了猎王。王只能继续往前。","28":"王到f4。它已经越过棋盘中线，正走进白方阵地。","29":"再用g兵将军。两个兵挡住了王的退路。","30":"王到f3，正好在白方棋子的包围中。","31":"象从d3退到e2将军。王被赶得更深了。","32":"王到g2。离白王所在的e1已经不远了。","33":"车到h2将军。车终于也参战了。","34":"王终于到了g1。它从g8出发，一直走到了棋盘另一端的第一横排。","35":"白王从e1走到d2。王让开后，a1的车前面通了，沿第一横排将军g1的黑王：将死！长易位也能将死，但拉斯克选择了走王。在一盘快棋里，弃后之后用14个回合把王一直赶到白方阵地的最深处，这是非常罕见的一盘棋。"}},"toketsu":{"t":"吐血之局","w":"赤星因彻","b":"本因坊丈和","ev":"于老中松平周防守府邸对局（下了四天）","d":"1835年","pl":"日本（江户）","lead":"这是围绕棋界最高职位“名人棋所”之争而下的一局。井上幻庵因硕派弟子赤星因彻挑战名人丈和。经过四天激战，因彻落败，据说他在棋盘前吐了血。","c":{"0":"1835年（天保六年），江户。这是在老中松平周防守府邸的棋会上下的一局。黑方是井上家的赤星因彻（七段），白方是名人棋所本因坊丈和。名人棋所是棋界最高地位，丈和与井上幻庵因硕争夺后得到了它。心有不甘的幻庵派出最得意的弟子因彻，打算一旦获胜就说“输给七段的人不配当名人”。对局历时四天，留下了围棋史上最有名、也最悲伤的故事之一。","1":"黑1下在左下小目（C4）。因彻从稳健的一手开始，显示出即使面对名人也要下自己的棋。","2":"白2（Q3）、黑3（R16）、白4（E16），四个角各放一子。白4是高目，比起实地更重视向外发展。","5":"黑5（P17）在右上守角，使右上坚固，为之后的战斗做准备。","6":"白6（E3）早早地挂左下黑角。丈和一开始就很积极，不让黑从容布局。","8":"黑7（R5）挂右下白Q3，白8（R9）从上方夹击。白想让右边黑子变弱，作为攻击目标。","9":"黑9（R11）从上方反夹白8。由于右上黑角稳固，黑可以在右边反过来攻击白。","10":"白10（P4）守右下角，把右边的战斗放到以后，先巩固自己的角。","11":"黑11（J3）下在下边中央，在白E3与白P4之间落子，不让白在下边围大空。","12":"白12（D6）从上方压住左下黑角，与白E3配合，想包住黑C4。本局最大的战斗由此展开。","13":"黑13（E4）紧贴在白子之间挤入，在被包围之前把白子分开。黑毫不示弱地应战。","16":"白14（D4）、黑15（D5）、白16（D3）。白钻到黑角下方，黑向上伸展。双方棋子互相被切断，都背着弱棋，是艰难的战斗。","19":"黑17（C5）、白18（E5）、黑19（F4）。黑从下方压住白E5，让白子保持上下分离。白左下的子必须在角上做活或向外逃。","20":"白20（C3）钻到黑角下方，一边掏黑角实地，一边设法在角上做活。黑21（B3）、白22（B2），角里的细致交锋继续。","22":"白22（B2）下到角上二线，整理白在角上的活形。黑角因此变小，但黑的外侧棋子变强了。","23":"黑23（C7）上到左边，从下方压住白的上方棋子（D6等）。白24（G2）沿下边伸展，为角上白子打开连接做活的路。","26":"黑25（H4）在下边压住白子的头，白26（E6）加强上方白子。下方白棋求实地，上方白棋求出路，黑同时盯着两边。","27":"黑27（B4）压住角上白子的上方，尽量缩小白的做活空间，为之后的攻击做准备。","28":"白28（C9）大步跨入左边，想为上方白子建立根据地，但常被认为是过分之着。这是典型的丈和式强硬下法。黑接下来要惩罚这一手。","31":"黑29（D8）、白30（D9）、黑31（E8）。黑切入白C9与上方白子之间，把白分成两块。左边的白C9、D9与中央的白D6、E6被拆散了。","33":"黑33（C2）。据说这是井上家秘密研究的新变化。一边压迫角上白子，一边攻击中央的白浮棋，一手两用。这是为击败名人而准备的“秘密武器”，从这里开始黑的优势逐渐明显。","36":"白34（D2）、黑35（B1）、白36（F3）。白急于连接下边棋子做活，中央白子因此迟迟得不到支援，成了黑的攻击目标。","38":"白38（A2）是一线的手，确保角上白子的眼位，稳稳做活。下方白棋安定后，白就能专心于上方的战斗。","40":"从黑37（G5）到白40（G7），中央白子向上逃，黑紧贴在旁边追赶，一边追一边加强自己。","42":"黑41（H7）、白42（G8）。白向中央上方逃，黑从外侧跟随。白越向上逃，黑的下边和左边就越坚固。","43":"黑43（E9）。左边白C9、D9被黑包围，陷入困境，中央白子也还没活。到这里因彻下得非常出色，一般认为已明显领先。面对名人，井上家的作战似乎很成功。","45":"白44（H8）让中央白子向上逃，黑45（D11）沿左边向上伸展，封住白C9、D9的上方。左边白子向上、向中央都快出不去了。","48":"黑47（H5）、白48（F5）。白想把中央与下边的子连起来，黑想撬开它们之间。对白来说，每一处连接都很重要。","50":"黑49（C12）使左边更加坚固，白50（C16）转向左上角。白暂时离开左下的苦战，去别处取利。","53":"黑51（M3）补强下边，白52（Q6）压住右边黑R5。黑53（G17）进入上边，阻止白左上扩大。","57":"白54（R6）巩固右边后，黑55（D17）、白56（C17）、黑57（E17）。黑在左上白角正上方落子，一边削减角地一边在上边展开。","58":"白58（C14）从左上角沿边展开，逼近左边黑子。白的左上与黑的左边正面相撞。","60":"黑59（J8）从上方压住中央白子，白60（G4）则提掉黑两子。左下白子终于稍稍喘了口气，苦战中的白稳稳拿下能拿的。","63":"黑61（O3）在下边右侧落子，白62（J17）去上边，黑63（F16）从外侧压住白的左上。战火在盘上各处蔓延。","66":"白64（M17）、黑65（B13）、白66（B14）。黑在左边边缘钻到白子下方，白设法安顿左上棋子。左边白C9、D9仍被黑包围。","68":"白68（B11）。从这里开始白的几手棋以及第80手，后来被传为“丈和的妙手”，精彩到被说成是“鬼魂教的棋”。白B11是在寻找连接被围的左边白C9、D9与左上白棋的通路。苦战中的白从这里开始反击。","70":"黑69（D10）想阻止白连接，但白70（E12）不应左边，先占中央要点。左边留有对白有利的手段，所以不必马上应。一边化解对方攻势一边夺回主动，是名人风范的一手。","72":"黑71（F10）压住中央白子后，白72（R13）转向右边。白暂停中央战斗，先阻止黑右上模样扩大。","76":"黑73（P11）、白74（R15）、黑75（Q16）、白76（O14）。白钻到右上黑角旁，落子连接右边与中央，为分断黑子做准备。","78":"黑77（P9）、白78（Q9）。白阻碍右边黑R5、P9与上方黑子的连接。右边黑子能否连上，还是被切断，局面紧张。","80":"白80（Q10）形成“空三角”，通常被认为是愚形。然而正是这一手，成为把右边黑棋分成上下两块进行攻击的据点。重功能而轻外形，常被举为“形愚而实妙”的典型，是著名三妙手的最后一手。从这里起白的分断攻击正式展开，形势逐渐向白倾斜。","83":"黑81（S6）、白82（S7）之后，黑83（R3）打入右下白角。在右边陷入困境的黑，想通过破坏白角同时求活、求地。","86":"黑85（S2）、白86（R4）。黑从一线紧白子的气，白从角内侧压住黑。双方都在数对方被吃前还剩几手。","88":"从白84（R2）到白88（Q2），在角上一、二线进行细致的对杀。谁先吃掉对方，一手之差就能决定胜负。","91":"黑91（Q4）提白一子，在右下角的对杀中领先一步。但白也在准备从外侧包围黑子。","95":"白92（N4）、黑93（R7）、白94（Q7）、黑95（O4）。白从下边绕到黑的外侧，黑想在右边和下边两处都连起来。黑棋越大，越难逃脱。","98":"白98（M4）从外侧包住下边黑子。黑在右下角和中央都没有马上能安心的形。","101":"从白96（N3）到黑101（O5），下边黑白并排向中央延伸，形成互相推挤的局面。","104":"黑103（P2）之后，白104（R4）提黑一子。右下角的对杀，白扳回了一步。","106":"黑105（N2），白106（S5）提黑一子。白守住了右下角，黑子无法在角上做活，只好向外逃。","107":"黑107（Q11）守护右边上方的黑子。下方黑棋困难，至少要让上方黑棋安全。白108（M2）、黑109（O1），下边边缘也继续着细致的争夺。","113":"白110（J4）、黑111（K2）、白112（H3）之后，黑113（K6）。下边黑子向中央出头，寻找活路。必须在被白包围之前确保出口。","116":"白114（L5）、黑115（L3）、白116（L6）。白像盖盖子一样压在黑子上方，缩小通往中央的出口。黑一边切断下边白子，一边设法出头。","120":"黑117（K7）、白118（L7）、黑119（J9）、白120（N9）。黑向中央大跳，白抢先从右侧堵住黑的去路。中央变成谁先变弱的较量。","125":"白122（J2）、黑123（K3），下边黑子总算连上了。黑125（N11）想把右边上方黑棋与中央黑子连起来。","128":"白126（O7）、黑127（N8）、白128（L11）。白也绕到中央黑子上方，从上下两面压住黑子。从第80手开始酝酿的分断态势逐渐显现。","132":"从黑129（M10）到白132（K10），黑白在中央互相切断。黑想突破白的包围，白一个个堵住黑的出口。","137":"从黑133（L8）到白136（P10），中央棋子更加纠缠。黑137（N13）向上大跳，想把中央黑子与上边连起来。","138":"白138（K8）提黑一子，中央开劫。双方在K8和L8反复提子，持续约30手。这个劫的胜负将决定中央黑子的命运。","143":"从黑139（K9）到黑143（J6），劫材与提回持续交替。黑143提白一子，让下边黑子轻松了一些。","148":"从白144（K5）到白148（K8），下边和中央继续找劫材、提回。白每找一次劫材，就在下边黑子周围得到一点便宜。","152":"白152（E11）是劫材，冲击左边黑子的弱点，逼黑应。劫争期间，白不断在各处找到黑必须应的手。","158":"从黑155（H2）到白158（C6），下边和左下也在找劫材，发生小转换。白158威胁左下黑角，黑159（B6）守住。","162":"黑161（G1）、白162（F1），下边边缘也发生提子争夺。劫争期间，小的争斗蔓延到盘上每个角落。","167":"白166（K8）再次提回后，黑167（M1）没有继续打劫，而是下在下边别处。这样中央的劫由白获胜，白可以把中央棋子连起来。黑在下边得到补偿，但中央黑子陷入了困境。","170":"白168（K11）、黑169（H10）之后，白170（P15）转向右上。白暂时安定中央，瞄准尚未完全活净的右上大块黑棋。","175":"从黑171（L13）到黑175（K14），黑向上边延伸，想把右上与中央黑子连起来。白174（O17）在右上角附近压缩黑的做活空间。","178":"白178（J14）打入上边中部，把黑子分成左右两块。从第80手开始准备的分断攻击在这里正式展开。黑必须同时照顾左右两边，处境非常艰难。","182":"从黑179（K15）到白182（G14），白在上边左侧也从外侧压住黑子。黑在左上的棋子也必须寻找做活空间。","190":"从黑183（F14）到白190（J13），黑白在上边左侧激烈地互相切断。白不断在黑子之间落子，破坏黑形。","193":"黑193（J11）提白一子，黑也拼命连接，寻找活路。但上边右侧的黑子仍有隐患。","199":"从白194（S14）到黑199（A16），白在外侧压住右上黑角，黑也在左上边缘下工夫。哪块大棋先变弱，是进入终盘前的关键。","201":"黑201（R14）提白一子，右边开始新的劫，双方在R14和R15反复争夺。右上黑棋能否活，就看这个劫。","206":"从白202（E14）到白206（M13），白一边找劫材，一边慢慢收紧对中央黑子的包围。劫争中，白的整体包围网也逐渐成形。","213":"从黑207（L17）到黑213（K18），黑在上边拼命连接。白把手伸到一线、二线，夺取黑的眼位。","222":"白222（L14）提黑一子。上边黑棋仍被分成两块，要两边兼顾已经很难。名人的分断攻击终于要开花结果了。","225":"黑225（R15）解消了右边的劫，右上黑棋总算活了。但在此期间白得到了上边中央，全局仍是白领先。","232":"黑229（P14）、白232（Q14），右上又出现小劫。黑到最后都不放弃寻找机会，但白应对得很细心。","239":"黑237（F12）、239（E13）在左上提回白子。尽管如此，仍补不回在上边中央的损失，全局差距并未缩小。","244":"黑241（P18）、白242（P19）、黑243（P14）、白244（N12）。细小的手一直持续，但白一个个下到中央的要点。胜负已几乎确定。","246":"白246（L8）之后，因彻认输。开局因彻凭井上家的秘密变化大幅领先，但丈和以第68手起的妙手和第80手“形愚而实妙”的一手反击，不断分断攻击黑棋，终于逆转。据说收拾棋子时，因彻把血吐在了棋盘上。他的身体大概早已被疾病拖垮，不久便去世了。对守住名人之位的丈和来说，这被称为一生最大的胜利，幻庵的计谋以失败告终。这是年轻的因彻以生命相搏的一局，至今仍被传颂。"}},"deepblue1997":{"t":"深蓝的胜利","w":"深蓝（IBM的计算机）","b":"加里·卡斯帕罗夫","ev":"与IBM深蓝的再战（六局比赛）第6局","d":"1997年","pl":"美国（纽约）","lead":"世界冠军卡斯帕罗夫，对阵IBM制造的国际象棋计算机\"深蓝\"，进行六局比赛。前五局打成平手，最后一局只下了19个回合就结束了。这是计算机第一次在多局的正式比赛中战胜世界冠军。","c":{"0":"1997年5月11日，纽约。世界冠军加里·卡斯帕罗夫，对阵IBM制造的国际象棋计算机\"深蓝\"，进行六局比赛。前一年的比赛是卡斯帕罗夫赢了，但这次面对变得更强的深蓝，前五局后比分是2.5比2.5。最后的第6局由深蓝执白。人和计算机到底谁更强？全世界都在关注这盘棋。","1":"白方把王前的兵走两格，占住中央，为棋子打开通路。","2":"卡斯帕罗夫走c6，准备下一步d5冲击e4，这是卡罗-康防御。它很稳固，当时常被用来对付计算机。","3":"白方把另一个兵也走到中央，两个兵并排站着。","4":"黑方走d5冲击e4，中心兵的争夺开始了。","5":"马到c3保护e4。一边出子一边防守，很自然的一步。","6":"黑方吃掉e4的兵，交换中心兵，让白方中心变小。","7":"马吃回来。白马站到了棋盘中央。","8":"黑方把马走到d7。这样等另一个马出到f6时，如果白方换马，黑方可以用这个马吃回。","9":"马跳到g5，这是瞄准f7和e6的尖锐计划。趁黑方王翼还没稳固，白方早早发起进攻。","10":"黑方把马出到f6，保护王的棋子多了。","11":"象到d3，沿斜线瞄准h7，对准黑方王翼。","12":"黑方走e6加强防守，也打开了f8象的路。但e6的兵也成了白马的目标。","13":"另一个马也从g1出到f3。白方准备好易位了。","14":"黑方走h6，想赶走g5的马。但在这个局面里，白方弃马于e6的走法早已为人所知。人们觉得像卡斯帕罗夫这样的大师选这步很奇怪，也有人认为他不小心弄错了走棋的顺序。这是胜负的分水岭。","15":"马弃在e6！用一个马换来的是：破坏黑王周围的兵，让黑方无法易位。据说深蓝是从事先存好的开局走法里走出这一步的。","16":"黑方没有马上吃，而是把后走到e7。在e线上，它对准了e6的马和后面的白王。马一动王就被将军，所以马逃不了。","17":"白方王车易位，让王离开。这样e6马的牵制就解除了。白方并不在乎马被吃掉。","18":"黑方吃掉马，子力领先。但黑王周围的兵已经被打乱，王的防守非常薄弱。","19":"象到g6将军。f7的兵不在了，斜线一直通到e8的王。","20":"王到d8。黑方再也不能易位，王被困在中间附近。黑方的棋子被自己的王挡着，很难活动。","21":"另一个象到f4，瞄准c7和b8，让黑王周围的空间更小。","22":"黑方走b5，在后翼腾出地方，准备把象出到b7，也给王找条退路。","23":"a4冲击b5的兵。白方想打开后翼的线路，让a1的车也加入进攻。","24":"黑方把象出到b7，沿长斜线瞄准g2。黑方的棋子终于开始动起来了。","25":"车到e1。在e线上瞄准e6的兵，以及后面e7的后。白方所有的棋子都加入了进攻。","26":"黑马到d5，这是中央的好格子，攻击f4的象，同时保护e6。","27":"象退到g3，继续瞄准c7和b8，保持对黑王的压力。","28":"黑王到c8，稍微安全一点，也让d8的车能动了。","29":"白方吃掉b5的兵。a线打开了，a1的车开始盯着a7的兵。","30":"黑方用兵吃回。但黑王周围的兵越来越少了。","31":"后到d3，瞄准b5的兵，也盯着f5格。白方的棋子一点点包围黑王。","32":"黑方把象退到c6，保护b5的兵。","33":"象到f5！可以被白白吃掉。但如果兵吃了它，e线上的兵就没了，e1的车就能直接够到e7的后。","34":"黑方用兵吃。这样从e1到e7的e线上什么都没有了。","35":"车吃掉e7的后。白方送出了马、象和车，但换来了最强的棋子——后。","36":"黑方用象吃回车。子力差不多，但黑王身边几乎没有掩护。","37":"c4！这个兵同时冲击b5和d5，黑方的防守棋子开始崩溃。白后也随时可以加入进攻。卡斯帕罗夫在这里认输了，大概是认为王太暴露，挡不住进攻。只有19个回合。这是计算机第一次在多局的正式比赛中战胜世界冠军，是一个历史性的时刻。从那以后，用计算机研究和练习国际象棋变得理所当然。"}},"seigen1933":{"t":"三三·星·天元之局","w":"吴清源","b":"本因坊秀哉","ev":"与秀哉名人的纪念对局（历时三个多月）","d":"1933—1934年","pl":"日本（东京）","lead":"19岁的吴清源（五段）与名人本因坊秀哉对弈。执黑的吴清源第1手下三三、第3手下星、第5手下天元，打破当时的常识，震惊棋界。对局多次打挂，历时三个多月，最终白胜2目。","c":{"0":"1933年秋，东京。黑方是19岁的吴清源（五段），白方是59岁的名人本因坊秀哉。吴清源出生于中国福建省，14岁东渡日本，是一位天才少年。这一年，吴清源和好友木谷实一起推广名为“新布局”的新下法，比起角上的实地更重视中央的力量，引起了很大反响。对手秀哉是世袭本因坊中的最后一位名人，站在棋界的顶点。新一代将如何挑战老名人，受到许多人的关注。对局多次打挂（暂停，改日续弈），历时三个多月。那个时代没有贴目，胜负只看棋盘上的地有多少。","1":"黑1是右上的三三（R17）。这是距两边第三条线的交点，一手棋就几乎能确保角上的实地。但向外扩张的力量较弱，当时被认为“不是第一手该下的棋”。面对名人，吴清源一上来就下了三三。","2":"白2是左上的小目（C16），即第三线与第四线的交点，是江户时代以来最基本的下法。名人不露惊讶，选了一手平常的棋。","3":"黑3是左下的星（D4），即两条第四线的交点。与三三相反，它更重视向外扩张而不是实地。黑在与右上三三相对的角上，放了一颗性格完全不同的棋子。","4":"白4是右下的小目（Q3），白又用小目占了空角。白打算一个一个地稳稳占角，在实地上领先。不管黑下出什么新招，名人的方针都不动摇。","5":"黑5竟然下在棋盘正中央——天元（K10）。天元到四面八方的距离都一样，能支援任何方向的战斗。但它很难成为实地，所以几乎没有人在布局阶段下这里。三三、星、天元——黑用三颗子摆出了角上实地、向外扩张、中央力量这三种思路。这个大胆的布局轰动一时，据说甚至有人说这是对名人的失礼。","6":"白6（Q16）是从斜上方压住右上黑三三的“肩冲”。白想把黑关在角上低位，自己在外侧筑起厚壁。这是对付三三的典型攻法，名人首先压制了黑新布局的出发点。","8":"黑7（R16）爬，白8（Q15）长。黑扩大角上的生存空间，白把墙壁向右边延伸。黑在这里不向外反推，是因为已经明确把三三这颗子的任务定为“角上实地”。","9":"黑9（P18）在上边二路跳，一边扩大角地，一边做成稳固的活形。这样右上角分工明确：角里是黑地，外侧是白的厚势。","10":"白10（R6）。位置正好同时配合上方右上的白墙（Q16、Q15）和下方右下的白Q3，是一手想把整个右边变成白阵的从容大棋。","11":"黑11（K4）在下边中央、天元正下方的四路。与天元K10纵向排列，瞄准从下边到中央的大模样。黑子全都下在高位，看得出黑重视势力胜过实地。","12":"白12（M3）。白从右下角一侧靠近，下在黑K4右边的三路。这是为了不让黑大围下边而尽早建立据点的一手。如果放着不管，黑下一手在这一带落子，下边可能就成了黑的大地。","13":"黑13（D10）在左边中央。左边有D4、D10，中央有K4、K10，黑子像一张网一样铺在棋盘的左下半边。不马上应白12，而是先占大场，也很有新布局的味道。","14":"白14（E16）在左上角再下一子，用两颗子守角。名人不受黑新下法的迷惑，稳稳把角变成自己的。到这里，方针泾渭分明：白是两个角加右边，黑是两个角加中央。","15":"黑15（M5）从上方罩住下边的白M3。黑想把白压在低处，自己在外侧筑墙。思路是：即使在下边让白得一些地，只要换成中央的力量就好。","18":"白16（O3）向右下白Q3方向扩大据点，接着黑17（L3）、白18（M4），双方在下边接触。白在三路一边巩固实地一边做活，黑从上方压住。双方都按自己的方针下棋。","20":"白20（C12）从左上的守角沿三路向左边拆。靠近黑D10，防止整个左边都成为黑地。名人的下法是在黑的模样变大之前，从边上一点一点地取地。","21":"黑21（G10）正好在左边D10和天元K10之间。这样黑子在四路高度横排成一列，从左边到中央形成一道大墙。黑不在意白的实地，一心扩大中央的势力。","22":"白22（F3）从下边一侧挂左下黑星D4。白在右下和下边已经有子，若这里也成地，整个下边就都是白的了。这是削黑大模样最下沿的一手。","25":"黑23（F5）罩住白F3，白24（J3）在下边向右拆，黑25（G4）再从上方压住。白在三路，黑在四、五路。白取地、黑取墙，这局棋的流向在这里再次重复。","26":"白26（C3）是左下黑星D4内侧的三三。钻到星位棋子的正下方去取角地。星位向外的力量强，但被点三三时守不住角地，这就是它的弱点。","28":"黑27（C4）从外面挡住，白28（D3）在角上做成活形。黑把角地让给白，换来C4、D4、F5、G4这道面向中央的厚墙。纵观布局，白在左上、右下、左下三个角和下边取地，黑则有右上角和中央的势力。中央的黑势能变成多少地，将决定此后的胜负。","29":"黑29（O16）下在右上白墙（Q16、Q15）左边的上边。既限制白墙向上边发挥作用，又把右上的黑角向上边扩展。这个位置不会太靠近白的厚势，恰到好处。","30":"白30（Q12）从右上的墙沿右边向下拆，建立根据地（做活的立足点）。这样右上的白和R6的白更容易联络，右边开始像白地了。","31":"黑31（Q10）打入右边星位，正好在白Q12和白R6之间。这是不让白把整个右边围成地的一手，也与黑中央的势力相呼应。从这里开始，右边将成为黑白交错的战场。","33":"白32（O15）贴在黑O16下方，动摇上边黑子的根基。黑33（N15）从左边挡住，堵住白向上边左侧和中央出头的路。黑想不让白子出来，把上边变成自己的势力。","35":"白34（N14）向下长，黑35（O14）就在白O15和白N14之间切断。被切断后，白子一分为二，各自都变弱了。黑让白在自己的势力范围里作战，想一边攻击一边得利。","37":"白36（O13）之后，黑37（P15）提掉白O15，这是本局第一颗提子。白38（P14），黑39（O15）粘上，右上的黑与上边的子牢牢连在一起。白虽然损失一子，但用O13、N13、N14向中央探出了头。","40":"白40（O10）从O13大步跳向中央，进到黑右边Q10和天元之间。白在黑中央的包围圈里建立了据点。对黑来说，在自己的势力里攻击白子也有乐趣。","41":"黑41（P7）下在右边下侧，从上方压住白R6，同时和Q10配合。这样右边的白子，上面的Q12和下面的R6被黑夹住，很难连络。黑在右边也想缩小白的地。","43":"白42（N13）把中央的白子连好，黑43（L15）就在上边向左长。上边的黑墙变长，从上边到中央逐渐成为黑的势力。黑不急于战斗，先扩大自己的阵地。","44":"白44（H17）从左上守角向上边拆，抢先限制黑上边势力的继续扩张。名人在这里同样是在黑模样扩大之前，把子下在容易成地的边上。黑大模样的边缘又被白占去了一处。","45":"黑45（R7）紧贴在右边白R6的上方。本局第一场大战从这里开始。黑打算切断R6和上方白子（Q12）的联络，把右边的白分成上下两块。白也不轻易退让，此后从右边到右下，双方互相切断的复杂局面持续展开。","48":"白46（S7）、黑47（S6）、白48（S8）。白在边上二路于黑R7的下方和上方落子，在R7周围增强力量。黑S6绕到白R6的右下，夺走了R6沿边轻松做活的空间。双方都在攻击对方的弱点。","52":"黑49（S5）、白50（Q7）、黑51（R8）、白52（R9）。白Q7插进黑R7和黑P7之间，接着黑R8、白R9，形成了互相切断的形状。右边双方的棋子都处于被切断的状态，谁先出现弱棋谁就会吃苦，是一场艰难的战斗。","55":"黑53（Q8）、白54（Q6）、黑55（Q9）。黑长出Q8、Q9，把R7、R8的黑子与上方的Q10连起来。白用Q6把下方的白R6、Q7连成一块。右边的黑虽然连成一串，但被白包围，气并不多。","58":"白56（R10）、黑57（O8）、白58（Q11）。白用R10、Q11把右边上方的白（Q12）和沿边的R9、S8连成一块。黑用O8加固中央一侧，堵住白子向中央出头的路。右边的白上下相连，黑与中央相连，战斗暂时平息。","59":"黑59（R4）这次打入右下角，进入白Q3的角地。同时瞄准与上方黑S5、S6联络，威胁白R6、Q6、Q7的根基。对白来说，是守角地还是守外面的子，成了困难的选择。","63":"白60（P6）、黑61（O6）、白62（O5）、黑63（N5）。白用P6、O5想把右边的白与下方的白连起来，黑用O6、N5从上方和左边压住。黑通过O6，让下边的墙（M5）和右边的P7、O8靠在一起。白选择保护外面的子，右下角仍留着黑的打入。","66":"白64（P4）把从右边下来的白子与下方的白Q3牢牢连在一起。接着黑65（R2）、白66（R3），角里的争夺继续。黑想在一、二路的低处做出在角上活棋的空间。","69":"黑67（S3）、白68（Q2）、黑69（S2）。黑在右下角的边上把子连起来，做成了活形。白的右下角比预想的小了很多，但作为补偿，白子在外侧（P4、P6、Q6）厚实地连在一起。黑削了地，白固了外势，这也是双方都说得过去的分寸。","70":"白70（N6）打在黑O6和黑N5之间，正是下边黑子与右边黑子的接缝处。目的是分断黑子，让其中一方变弱。黑71（O7）马上粘上，把右边的黑连成一块。","74":"白72（M7）、黑73（M8）之后，白74（L4）冲进下边黑K4和L5之间，想把黑L3孤立在下边的白子中。接着黑75（N4）、白76（N3），下边的白在三路与右边的白连上了。","78":"黑77（J4）把下边的墙向左连起来，白78（K3）堵住黑L3的出路。黑L3这一子只剩一口气（L2）。黑弃掉这一子，优先保住J4、K4、L5、M5、N5、N4这道面向中央的长墙。不拘泥于小子，守住大构想，这是黑的判断。","79":"黑79（L9）下在天元K10的右下，使中央的黑更加厚实。下边的黑墙、右边从O6到Q10的黑子、天元、左边从D10到G10的黑子，围绕着中央的大模样连成一圈。白在角和边上赚地，黑能把中央围成多少地？到这里形势被认为接近均衡，棋局即将进入中盘战斗。","80":"白80（C6）从左下的白角向左边上行，在黑墙旁边的三路落子。既压缩黑的左边，也为以后打入左边做准备。黑81（E4）粘住D4与F5、G4之间的断点，使墙壁连成一体。","82":"白82（C10）贴在左边黑D10的左侧（靠边一侧）打入。如果整个左边都成为黑地，黑中央的模样会变得非常大。白不允许这样，要在黑阵势的最左端做活。","85":"黑83（C9）、白84（D9）、黑85（C8）、白86（D8）。黑从边的一侧挡住白C10的下方，白则在黑墙内侧长出D9、D8。双方互相把对方往边上挤。双方的棋子都还说不上已经活了。","88":"黑87（C11）切断白C10和白C12，是严厉的一手。白88（B10）向边上退，扩大C10做活的空间。黑的目的是把打入的白子切断后加以攻击。","91":"黑89（B11）、白90（D11）、黑91（E10）。黑用B11延长切断的子，但白用D11从上方压住黑D10的头。黑E10把D10与天元一侧连起来，守住左边的黑墙。切断的黑子B11、C11夹在白子之间，气越来越少。","96":"白92（B12）之后，黑B11、C11两子只剩一口气。黑不救这两子，而是用黑93（D7）堵住白D9、D8的下方。接着白94（E11）、黑95（F10）、白96（C7），左边变成双方都想吃掉对方棋子的形状。黑选择吃子而不是救子，是大胆的判断。","98":"黑97（A9）之后，白98（A11）提掉黑两子（B11、C11）。白在左边的边上做成活形，黑的左边地比预想的小了。作为交换，黑99（E8）之后，白D9、D8两子只剩一口气（E9），黑随时可以提掉。被提两子又提回两子，左边大致是扯平的结果。","100":"白100（B4）扩大左下的白角，同时压住黑C4的下方。白C3、D3的角通过B4和之后的C5，与左边的C6、C7连起来。从左下到左边的白子成了一块连续的强棋。","101":"黑101（S14）从右上的黑角向右边滑行，侵消白右边（Q12、Q11）上方的地。白102（C5）巩固左下时，黑103（R13）再进一步，白104（S12）总算守住右边的地。双方地盘的分界线一点一点确定下来。","105":"黑105（K17）下在上边中央、白H17的右边。阻止白上边的地继续向右扩张，同时与上边的黑L15、N15配合。上边左边是白，右边是黑，看来会围绕分界线展开战斗。","106":"白106（G3）这次在下边紧贴黑G4的下方。白想用自己的子填补F3与J3之间的空隙，巩固下边的地。黑107（E3）插入白D3和白F3之间去切断。看起来不大，却是决定地界的重要交锋。","108":"白108（E6）下在黑左下墙壁的上方，D4、E4稍上的位置。与左边的白C5、C6配合，戳黑墙的背后。黑109（F6）马上从上方压住，阻止白向中央出头。","113":"白110（E2）、黑111（F2）、白112（D2），下边的边上继续争夺棋子，黑113（H3）打入白G3和白J3之间。这是想把白下边的子分散开，缩小白地的一手。黑想尽量减少自己墙下面的白地，哪怕一点也好。","116":"黑115（H4）把H3与墙连起来，白116（G2）从下方把F3、G3连上。黑F2一子只剩一口气（F1），几乎是被吃掉的形状。下边的白虽然被戳了空隙，总算连成了一体。","117":"黑117（F17）打入左上白守角（C16、E16）与上边白H17之间的上边三路。这是削减白上边的地，并伺机分断白子加以攻击的一手。从这里开始，上边左半部展开了新的战斗。","120":"白118（J17）加强上边的子，黑119（D17）更深入左上角。白120（C17）是守角的一手。黑想夺取白角最上方、二路附近的地方。白一边守角，一边准备从外面收紧黑棋。","124":"黑121（G16）、白122（H15）、黑123（G15）、白124（K15）。黑用G16、G15向中央长，要把左上的白与上边的白H17分开。白用H15、K15把上边的白向中央一侧连接，威胁上边的黑K17。上边的战斗中，黑白双方的棋子轮流探头。","127":"黑125（H16）、白126（J16）、黑127（H14）。黑用H16从上方、用H14从下方压住白H15。白H15一子被黑包围，只剩一口气（J15）。黑一边把中央上方变成自己的，一边逐一削弱白子。","130":"白128（L16）、黑129（M15）、白130（L17）。白用L16、L17把黑K17一子关在上边，同时让上边的白子成了活形。黑K17几乎动弹不得了。结果是黑得到中央上方，白守住上边的地。","133":"黑131（P13）、白132（P12）、黑133（Q13）。黑压住右边白子的根部，把右上的白Q16、Q15、P14与右边的白Q12切断。右上的白子被黑包围，形状很苦。右上角作为黑地已经相当确实了。","135":"白134（E7）从左下向黑墙内侧前进一步，黑135（E9）提掉白D9、D8两子。之前黑在左边被提了两子，这样就把被提的数目扳了回来。左边的黑子从此安全，从左边到中央的黑地也渐渐明确。","137":"白136（F7）、黑137（G7）。白在黑左下墙的上方排出E6、E7、F7，想向中央出头，黑用G7挡住。黑中央的模样从下方也一点点被削减。白不大举深入，而是一处一处缩小边缘的作战。","138":"白138（N18）进入上边右侧、黑P18和O16左边的二路。这是从上边一侧缩小黑右上地的一手。之后白148（O18）再向右推进，黑上边的地被一点点削减。","139":"黑139（C18）这次打入左上白角上方的二路。在白角（C16、C17、E16）的上方，黑还有做活的余地。如果在这里活了，白左上的地就会大大减少。这是要在白厚实棋子旁边做活的大胆一手。","145":"白140（E17）、黑141（E18）、白142（D16）、黑143（D18）、白144（G18）、黑145（B17）。黑在二路排出C18、D18、E18，用B17深入角里。白用E17、D16加固外侧，用G18阻止黑向右扩展。在白角的上方，黑想在狭窄的地方做活，细腻的手顺还在继续。","150":"白146（B16）、黑147（B18）、白148（O18）、黑149（P19）、白150（F18）。黑在左上角上方连成一块，白用F18等从外侧收紧。白的左上角只剩下B16到E16一线以下的部分。黑在白的地盘里让棋子活了下来，大大减少了白左上的地。这期间白在右上也用O18削减黑地，细腻的交锋还在继续。","152":"白152（G12）。白终于进入黑中央的包围圈。G12位于左边的白（E11、D11）与上方白子之间，正是黑厚势的空隙。白如果在这里做活，或与周围的白子连上，黑的中央就成不了地。从这里开始，是本局最大的高潮。","153":"黑153（K14）下在白上边K15的正下方，堵住白把G12与上边白子连起来的道路。同时，它也是连接中央黑子上下的一条粗壮通道。黑想把白分成上边和中央两部分，攻击其中之一。","156":"白154（J15）救出上边的白H15，黑155（F14）之后，白156（H11）。白在中央再下一子，与G12配合，在黑的中央扩大立足点。黑的中央正被上方和左边的白一点一点渗入。","159":"白158（E5）是戳黑左下墙内侧的一手。白如果再下F4，黑墙就会在E4和F5之间被切断。所以黑159（F4）牢牢粘上。黑在中央战斗之前，先把自己墙上的弱点一个一个补好。","160":"白160（H8）。这是本局最有名的一手。在黑中央模样的下方、被黑G7、G10、K10、L9等包围的宽阔地带，白只放了一颗子。据说这一子瞄准着黑子与黑子之间连接的多处空隙，黑无法一次全部守住。以这一手为契机，白开始一个接一个地向黑中央的地下手。曾有传言说这手棋不是秀哉自己、而是弟子发现的，但并没有确切的说法。","161":"黑161（J8）下在H8右边，阻止白在天元下方、与下边黑墙之间扩展。这是守住看起来最大地方的普通应手。但是，白的下一个目标却在别处。","162":"白162（K12）这次下在天元K10的上方。与白G12、H11配合，想把黑的中央分成上下两块。先用H8在下方动摇，马上转到上方。黑每守住一处，白就去碰另一个弱点，这是巧妙的手顺。","165":"黑163（F12）下在G12左边，想把白G12与左边的白分开。白164（F11）寻求连接，黑165（H10）挡住白H11的下方，不让白中央的子向下出头。中央的黑白棋子纠缠在一起，双方都想切断对方。","168":"白166（J14）、黑167（J12）、白168（J11）。白用J14把上边的白向下长，用J11与中央的白H11连上。黑J12是切断白上下的子。中央成了许多棋子时断时连的非常细腻的战斗。","172":"黑169（J13）、白170（K13）、黑171（K11）、白172（F13）。白用F13向左侧的白伸手，想把中央的子与左边、左上的白连起来。原本是黑中央厚势的地方，如今正变成白子穿行的通道。","175":"黑173（L14）救出K14的黑子，接着白174（J10）、黑175（J9）。白用J10进入天元的紧左边，黑用J9从下方挡住。白子一直进到天元K10的左邻，黑中央的地越来越小。","178":"白176（H12）把中央的白连好，黑177（G14）之后，白178（N9）。这次进入中央右侧、黑L9和黑O8之间。黑的中央从左右两边都被白侵入，已经不太可能成为大地了。白在棋盘的另一侧也不放过黑的弱点。","180":"黑179（D14）守住左上的黑，白180（N8）再向下长。白用N9、N8想把右边O6到O8的黑子与中央的黑L9、M8分开。右边的黑子被白包围，气很少，这里正成为新的弱点。","186":"黑181（T7）、白182（T9）在右边边上交换之后，黑183（N7）挡住白N8的下方，白184（D13）、黑185（M11）之后，白186（P8）。这是切断黑P7和黑Q8的锐利一手。右边O6、O7、O8、P7、N7的黑五子只剩一口气（O9），R7到Q10的黑五子也只有两口气。白一手棋同时瞄准了黑的两块棋。","189":"黑187（M6）提掉白N6，白188（O9）之后，黑189（L7）提掉白M7。这样O6到P7的黑五子气多了，和下边的黑连起来得救。黑虽然提了白两子，但这期间白已用O9把手伸向右边另一块黑棋。","192":"白190（F8）、黑191（G8）之后，白192（P10）。右边R7、R8、Q8、Q9、Q10的黑五子只剩P9一口气。黑即使下P9提掉白P8，白也能马上在P8扑回把黑一起提掉（倒扑），所以这五子已经救不了了。从白186的切断开始，白在右边得到了很大的便宜。黑在中央构筑的势力中，右侧的子没有变成地，反而成了白的猎物。","197":"黑193（R12）、白194（S11）、黑195（C14）、白196（E14）之后，黑197（G11）。中央白G12、H12、H11、J11、J10五子只剩G13一口气。黑想在中央吃掉白棋，把右边的损失扳回来。白中央的子能否得救，是胜负的分水岭。","198":"白198（E12）提掉黑F12。这样白中央的五子在F12也有了气，从F12或G13任何一处都能与左侧的白连起来。黑堵住一处，白就从另一处连上，所以白中央的子已经不会被吃了。突破黑厚势的白子活了下来，这是决定本局胜负的场面。","203":"黑199（E15）、白200（E13）、黑201（D15）、白202（B14）之后，左边上侧也定型了，从黑203（B3）开始进入官子（终盘确定地界的阶段）。黑B3从一、二路进入左下的白角，想多少削减一点白地。从这里开始，是围绕一目、两目的细腻着法。","206":"黑205（Q1）、白206（P1）、黑207（R1）、白208（P3）。在右下角的一路，黑削了一点白地，白牢牢守住自己的角。在官子阶段，一路上的一手就直接是一两目的差距。大战结束后，名人和吴清源都毫不松懈。","214":"黑209（B5）、白210（A3）白提掉黑B3，接着黑211（A6）、白212（B6）、黑213（A7）、白214（A5）又提掉黑B5。在左下的边上，白提掉两子守住了自己的地。黑也在左边上方（A6、A7）削减白地，双方各得一点小利。","220":"黑215（S13）、白216（N11）、黑217（R11）、白218（M12）、黑219（L12）、白220（M10）。在中央的右侧，白也用N11、M12、M10推进，进一步缩小了黑中央剩下的地。本应在天元周围展开的黑地，现在只剩下细细的一条。","224":"黑221（S10）、白222（S9）、黑223（T12）、白224（T10），白提掉右边边上的黑S10。右边的白地一目也不让地定型了。即使黑想扳回一些，白也仔细应对，不露丝毫破绽。","232":"黑225（B13）、白226（A15）、黑227（C13）、白228（A13）、黑229（F15）、白230（G17）、黑231（F16）之后，白232（C15）。从上边左侧到中央的黑大块（18子）因这手C15只剩G13一口气。白一边收左边的官子，一边给黑大块制造了意想不到的危险。黑必须马上应对。","233":"黑233（L13）提掉白K12、K13两子。这样黑大块在K12、K13两处有了气，与中央的黑连上，安全了。虽然很危险，黑用这手提两子保住了大块。名人如果能吃掉这块棋就能一举获胜，但吴清源没有看漏。","246":"白234（N17）、黑235（L11）、白236（F9）……白244（G13）、黑245（F19）、白246（G19）。白用G13把中央的子与F13连上，F19、G19也定下了上边边上的分界。剩下的只有一两目的小官子。数一数棋盘上的地，差距非常小。","249":"白248（A16）之后，黑249（M13）打吃白M12（再一手就能提掉的状态），白250（N12）粘上。中央最后的分界也定下了。黑251（R5）整理好右下黑棋的形状，剩下的手已经不多了。","252":"白252（M9）终局，白胜2目。执黑的吴清源用三三、星、天元的新布局在中央建立了强大的势力。但名人秀哉稳稳拿下角和边的实地，进入后半盘后，从第152手开始打入黑的中央。从第160手H8开始动摇中央，又用第186手P8的切断形成吃掉右边黑五子的局面，这些都非常关键，黑中央的势力没能如预想般变成实地。没有贴目的时代，先行的黑被认为有利，因此执白胜出显示了名人的深厚实力。另一方面，19岁的吴清源与名人只差2目，使新布局在棋界留下了深刻的印象。吴清源后来在十番棋中接连击败当时的一流棋手，成为代表昭和时代的棋士。"}},"century1956":{"t":"世纪之局","w":"唐纳德·伯恩","b":"鲍比·费舍尔","ev":"第三届罗森瓦尔德杯赛（罗森瓦尔德纪念赛）","d":"1956年","pl":"美国（纽约）","lead":"13岁的鲍比·费舍尔战胜了美国强手唐纳德·伯恩。第17回合，费舍尔让对方白白吃掉自己的后，然后一个接一个地把棋子赢回来，最后用小子们围捕白王。费舍尔后来成为了世界冠军。","c":{"0":"1956年10月17日，在纽约马歇尔国际象棋俱乐部举行的罗森沃尔德杯（罗森沃尔德纪念赛）上下出的一盘棋。这是邀请美国顶尖棋手参加的强大比赛，执黑的博比·菲舍尔只有13岁，是参赛者中年纪最小的。白方唐纳德·伯恩26岁，是1953年美国公开赛冠军，也是当时美国最有代表性的大师之一。菲舍尔在整个比赛中的成绩并不突出，但仅凭这一盘棋，他的名字就传遍了世界。汉斯·克莫赫在《国际象棋评论》杂志上称它为“世纪之局”，这个名字一直沿用到今天。让我们和Musowl一起一步一步地看，13岁的少年是怎样战胜成年大师的。","1":"白方把马跳到f3。它控制中心的e5和d4，也能保护王翼，是非常沉稳的开局。白方还没有决定兵的走法，之后可以走成各种阵形。","2":"菲舍尔也把马跳到f6，控制e4和d5。和白方一样，他先不决定阵形，观察对手的走法。","3":"白方走c4。这个后翼的兵从侧面控制d5格。目的是让黑方不容易把兵放到d5，并在中心多占空间。","4":"黑方走g6。下一步把象放到g7，从长斜线上注视中心。这是菲舍尔从小就喜欢的阵形：先稳住，再强力反击。","5":"白方把另一个马跳到c3。它更加控制d5和e4，之后白方可以用d4、e4把兵排在中心。","6":"象来到g7。现在它在f6马的后面，但只要马一动，从h8到a1的长斜线就会一下子打开。黑方也做好了易位的准备。","7":"白方走d4。用c4和d4两个兵占据中心。如果黑方用d5回应，就会形成名叫“格林菲尔德防御”的开局。","8":"黑方王车易位。王移到安全的g8，f8的车也靠近了中心。年轻的菲舍尔先让自己的王安全，再开始战斗。","9":"白方把象走到f4。它沿斜线注视c7和b8，也控制e5。但白方的王还在中间的e1，还没有做好易位的准备。","10":"黑方走d5，在中心冲击c4的兵。形成了格林菲尔德防御。黑方的计划是先让白方占据中心，然后再攻击这个中心。","11":"白方的后很早就出到b3。它对d5施加更多压力，也沿b线瞄准b7的兵。这是一步有力的棋，但后出得太早，容易被对方的棋子追着跑。","12":"黑方吃掉c4的兵。吃过来的兵正好斜着攻击b3的后，所以白方只能吃回来。这样黑方减少了白方一个中心兵。","13":"白方用后吃回c4的兵。后来到棋盘中央附近，注视d5和f7。但这个后之后会一次又一次被黑方的棋子追赶。","14":"黑方走c6。控制d5和b5，不让白方的后和马进去。这也为之后用b5赶后做准备。","15":"白方走e4。d4和e4两个兵整齐地排在中心。单看外形，白方占了很大空间，似乎下得很舒服。","16":"黑方把马走到d7。准备从这里跳到b6去赶后。同时也为把兵推到e5、冲击白方中心做准备。","17":"白方把车走到d1。从后面支持d4的兵，加强d线。但白方在易位之前就动了车，王还留在中间的e1。","18":"马跳到b6，攻击c4的后。白方的后又得走开。黑方一边出子，一边让对手浪费步数。","19":"后逃到c5。从c5可以注视e7的兵，也想压住黑方的后翼。但后已经冲得太靠前，处在容易被黑方棋子攻击的位置。","20":"象走到g4，攻击f3的马。马后面的d1上有车，所以马一动，车就会被吃掉，这叫“牵制”。f3的马保护着d4和e5等重要格子，现在白方很难动它了。","21":"白方把象走到g5。它攻击f6的马，想阻止黑方动这个马再走e5。但白方还有棋子没出动，也没有易位。很多人认为，这里把象走到e2、准备易位会更好。","22":"马跳到a4！这是本局第一个大惊喜。a4的马同时攻击c5的后和c3的马。如果白方用c3的马吃掉它，黑方就用f6的马吃e4的兵，同时攻击c5的后和g5的象。白方的王还在中间会受到攻击，所以白方不能吃这个马。据说看到这一步，周围的人都聚到棋盘旁边来观看。","23":"白方没有吃马，而是把后逃到a3。从这里仍能沿斜线注视e7的兵。白方选择了损失最小的应对方法。","24":"马吃掉c3的马。那个马正是保护e4兵的棋子。这样黑方就除掉了e4的保护者。","25":"白方用兵吃回。子力相等，但白方c3和d4的兵变得有些松散。而且已经没有棋子保护e4的兵了。","26":"马吃掉e4的兵！从e4攻击c3的兵和g5的象。白方中心整齐的兵阵被打乱，e线正在打开，中间白王的前方变得一览无遗。","27":"白方用象吃掉e7的兵。从e7同时攻击黑方d8的后和f8的车，这是双重攻击。白方吃回一个兵，同时攻击黑方的大子，是有力的反击。","28":"黑方把后走到b6。这是大胆的一步，意思是：f8的车你可以拿走。如果白方吃车，黑方用象吃回，这个象接着会追赶a3的后。黑方认为，白王还留在中间比一个车更重要。b6的后也注视着d4的兵。","29":"白方没有吃车，而是把象出到c4。这样空出f1，下一步就可以易位，把王移到安全的地方。白方也知道，王的安全是最大的问题。","30":"马吃掉c3的兵！从这里攻击d1的车。如果白方用后吃这个马，黑方可以把车走到e8，沿直线攻击e7的象和后面的王。黑方的棋子一个接一个地聚集到白王周围。","31":"白方把象走到c5，攻击黑方b6的后。如果黑方只是把后逃开，白方下一步就能易位。但因为象离开了e7，e线已经向黑方的车打开了。","32":"车走到e8，沿e线将军！e7的象已经走到c5，所以e线从e8到e1完全打开。在救后之前，黑方先对白王下手。","33":"王走到f1。这样白方再也不能易位了。h1的车也被王挡住，很难出来。黑方得到了一步的时间，但b6的后仍然被c5的象攻击着。","34":"象走到e6！这是本局最有名的一步：黑方让后白白被吃。e6的象攻击白方c4的象，吃掉它时就是将军。如果白方用c4的象吃e6，黑方就用后从b5将军，再用马连续将军，最后王被自己的棋子包围、动弹不得，形成“闷杀”。菲舍尔写道，如果改走马到b5，白方吃掉f7的兵就会让黑方输棋。13岁的少年早已看到了弃后之后很远的地方。","35":"白方吃掉了黑方的后。只数棋子的话，白方遥遥领先。但现在黑方的棋子要一边追赶白王，一边一个接一个地把子吃回来。","36":"象吃掉c4的白象，将军！从c4经过d3、e2瞄准f1的王。黑方的反击从这里开始。","37":"王逃到g1。黑方的车控制着e线，几乎没有别的地方可去。在g1，王被h1的车和g2的兵关住，几乎动不了。","38":"马跳到e2将军。王只能回到f1。黑方用将军捆住白方的手脚，同时为下一次吃子做准备。","39":"王回到f1。现在e2的马挡在c4的象前面。只要这个马一动，后面的象就会将军f1的王，这叫“闪击将军”。","40":"马吃掉d4的兵，闪击将军！因为马动了，c4的象现在将军f1的王。被将军时，不管马在做什么，都必须先处理王。","41":"王走到g1。白方一直被将军，没有时间做别的事。","42":"马再次跳到e2将军。王只能回到f1。黑方可以一次又一次地将军，每次都在寻找吃子的机会。","43":"王又走到f1。白方只能重复同样的走法。这种一边将军一边吃子、再回来的走法，因为像在转圈，被叫做“风车”。","44":"马走到c3，又是闪击将军！c4的象将军f1的王，同时c3的马攻击d1的车。白方正被将军，救不了车。风车又准备吃掉一个子了。","45":"王走到g1。黑方可以继续将军，但在这里先停一下，把b6的白象吃回来。","46":"兵吃掉b6的象。吃掉黑后的那个白象也没有了。因为a7的兵动了，a线打开，a8的车攻击a3的白后。数一数子力：黑方有两个车、两个象和一个马；白方有后、两个车和一个马。黑方下一步还能吃d1的车，所以黑方吃回的已经超过了后的价值。","47":"白后逃到b4。从这里同时攻击c4的象、c3的马和b6的兵，是一种犀利的逃法。白方拼命想吃回点什么。","48":"车走到a4！再次追赶后。a4的车受c3的马保护，后一离开，它还能保护c4的象。白后一个黑子都吃不到，只能逃走。","49":"白后吃掉b6的兵。至少吃回了一个兵。但与此同时，轮到c3的马去吃d1的车了。","50":"马吃掉d1的车。黑方用两个车、两个象和一个马对抗白方的后、车和马，明显领先。白方h1的车仍然被关着。","51":"白方走h3。为王在h2做出一个退路。王一走到h2，h1的车终于能出来了。这也能防止黑方一直威胁白方的底线。","52":"车吃掉a2的兵。白方后翼没有兵了，再也没有东西能挡住黑方那边的兵。车进入白方的第二横线，还能瞄准白王旁边的f2。","53":"王走到h2。现在h1的车终于可以在第一横线上自由移动了。白方想办法让剩下的棋子参加战斗。","54":"马吃掉f2的兵。从f2攻击h1的车和h3的兵。白王周围的兵又少了一个。","55":"白方把车逃到e1，并在e线上和黑方的车对上，提出交换。目的是减少一个黑方的进攻棋子。","56":"黑方交换车。子力多的一方，交换通常是有利的。白方在用马吃回e1之前，先用后将军。","57":"后走到d8将军。e8的车没有了，第八横线一直通到g8的黑王。白方先插入这个将军，打算之后再把车吃回来。","58":"黑方用f8的象挡住将军。象来到王的旁边，防守也稳固了。","59":"马吃回e1的车。白方有后和马；黑方有车、两个象和马。把棋子的力量加起来，黑方明显占优。","60":"象走到d5。注视f3格和g2的兵，还从斜线后方保护a2的车。黑方把棋子一个个集中到互相支持的好位置。","61":"马回到f3。它受g2的兵保护，是唯一守护白王的棋子。白方用后和马努力抵挡黑方的进攻。","62":"马走到e4。进入中心，靠近白王。下一步黑方想把f8的象走到d6，将军h2的王。","63":"白后走到b8。攻击b7的兵，同时沿第八横线把f8的象牵制在g8的王上。象一动，王就会被将军，这阻止了黑方用象将军的计划。","64":"黑方走b5。兵前进两格，躲开后的攻击。在b5它受c6的兵保护。将来黑方也可以把这个兵继续往前推。","65":"白方走h4。h兵前进，希望有机会用h5打乱黑王周围的兵。白方能做的事已经不多了。","66":"黑方也走h5。挡住白方的兵，保持黑王周围的阵形稳固。黑方不急，稳稳地下。","67":"马走到e5。从中心攻击f7。另外，如果马跳到d7，被牵制的f8象就会受到后和马两个子的攻击。这是白方最后的反击希望。","68":"王走到g7。解除f8象的牵制，同时保护它。现在象可以自由行动了。黑方做好了最后进攻的准备。","69":"王走到g1。留在h2的话，可能会被解放出来的象从d6将军，所以白方似乎先避开了。但白王附近几乎没有防守的棋子。","70":"象走到c5将军！从c5经过d4、e3、f2瞄准g1的王。现在黑方的小子们开始追捕白王。","71":"王走到f1。白王向棋盘左边寻找出路。但黑方的车和象正在那里等着，王慢慢被赶到棋盘的另一边。","72":"马跳到g3将军。王被赶到e1。这个马也挡住了王回到棋盘右边的路。","73":"王走到e1。它不能回到f2或g1，只能往左逃。黑方的网慢慢收紧。","74":"另一个象出到b4将军。从b4经过c3、d2瞄准e1。王被赶到更左边的d1。","75":"王走到d1。白方的后和马在棋盘的另一边，没法来帮助王。","76":"象从d5走到b3将军。从b3经过c2瞄准d1。这个象之后还有一个重要的任务：保护最后那步车要去的格子。","77":"王走到c1。几乎没有可以逃的格子了。黑方的棋子一个个封住白王周围的格子。","78":"马跳到e2将军。从e2攻击c1。王只能逃到b1。","79":"王走到b1。它几乎被赶到了棋盘的角落。","80":"马跳到c3将军。从c3攻击b1，同时控制d1。王只能回到c1。","81":"王走到c1。这将是它最后的格子。c3的马控制b1和d1，马上要来的车将控制b2和d2。","82":"车走到c2，将杀！c2的车受b3的象保护，王不能吃它；c3的马控制b1和d1，车控制b2和d2。车、象、马三个子织成了将杀的网，另一个象也帮忙把王赶到了这里。白王从g1一路被追到棋盘另一边的c1，白后直到最后什么也做不了。伯恩本来可以早点认输，但据说他是出于对少年精彩下法的敬意，才一直下到被将杀。第11回合马的跳入、第17回合弃后的决断、用“风车”把子吃回来，最后由小子们织成将杀之网。这盘棋之后，菲舍尔14岁成为美国冠军，1972年成为世界冠军。"}},"oshiro1849":{"t":"秀策的第一局御城棋","w":"本因坊秀策","b":"安井算知（九世）","ev":"御城棋（每年在江户城举行的对局）","d":"1849年","pl":"日本（江户）","lead":"御城棋是各围棋家元的棋手每年在将军城中对弈的盛会。20岁的秀策这一年首次出场，执黑胜11目。由此开始了他在御城棋中19战全胜的不败纪录。","c":{"0":"1849年。秀策前一年被定为本因坊家的继承人，这一年首次出场御城棋。据说御城棋多是事先在别处下好，再到城中复盘重摆。","1":"黑1下在右上小目（R16）。秀策一如往常，从稳健的小目开始。","4":"白4（C15）挂左上黑D17，布局阶段左上就开始了战斗。","5":"黑5（C11）从下方夹击挂过来的白子，不让白在左边轻松安定。","12":"白12（C17）。左上角归白，黑得到外侧。双方都可接受的转换。","13":"黑13（J17）利用外侧黑子，在上边展开。","15":"黑15（C5）占据最后一个空角——左下角。四个角都有子了。","16":"白16（E4）立刻逼近这颗黑子，左下也打了起来。","19":"黑19（D2）牢牢确保左下角的实地，是秀策式的稳健下法。","23":"黑23（E5）从白子之间出头，加强左下黑棋。","29":"黑29（F11）补强左边黑子，同时着眼中央。","30":"白30（H4）在下边展开，一边压迫左下黑棋，一边构筑自己的阵地。","31":"黑31（O3）挂右下白角。","33":"黑33（R3）紧贴白角的子。此后黑在外侧，白沿边上的三线伸展。","43":"黑43（Q8）。右边形成了上下相连的黑色厚壁。白取得角和边的实地，黑获得外势。","44":"白44（L17）打入上边黑子之间，不让黑阵地过大。","50":"白50（R18）钻进右上黑角下方，瞄准角地。","51":"黑51（P13）。黑背靠右边厚壁，从右边到中央构筑大阵地。","52":"白52（D10）打入左边黑子之间，左边黑白纠缠在一起。","63":"黑63（B10）在左边边缘落子，不让白子在这里建立根据地。","65":"黑65（G3）也侵入下边白阵，削减白地。","73":"黑73（K17）巩固上边黑子，让白44那颗子陷入困境。","76":"白76（P11）打入黑右边阵地。这颗子是死是活，将大大影响地的多少。","77":"黑77（Q11）从厚壁一侧应对，把白赶向中央。守地的同时进攻，是秀策式的沉稳应手。","80":"白80（N10）向中央逃出，试图摆脱黑的追击。","85":"黑85（N12）一边攻击，一边扩大上边和右边的实地。借攻得利，运筹巧妙。","91":"黑91（J7）下在下边白子上方，从中央方向压住白阵。","100":"白100（S17）在右上角动手，想削减黑的角地。","119":"黑119（R17）稳守右上角，化解了白的手段。","122":"白122（G6）绕到左下黑子外侧，企图切断它与中央黑子的联系。","131":"黑131（M5）在下边中部楔入白阵。","140":"白140（B4）在左下黑角动手，左边边缘开始了细致的提子争夺。","156":"白156（A8）提黑两子。左边边缘的争夺在双方互有所得后平息。","158":"白158（L10）。白在中央仍有子，试图削减黑中央的实地。","162":"白162（O12）提黑一子。尽管如此，黑右边的阵地仍然很大。","172":"白172（K18）。从这里进入官子，先确定上边的边界。","186":"白186（T16）在右上边缘削减黑地。官子阶段，双方都先下最大的地方。","205":"黑205（Q18）封住上边右侧，确定实地。","223":"黑223（P10）确定右边黑地与逃向中央的白子之间的边界。","233":"黑233（Q9）提白一子。黑右边的实地基本守住了。","239":"黑239（A6）提白一子，左边边缘形成劫。一目一目的争夺一直持续到最后。","260":"白260（T6）提黑一子，右下边缘也成劫。黑在263（T5）提回。","267":"267手终局，黑胜11目。没有冒大险，而是边攻击边自然扩大实地，是秀策式的胜法。这是他御城棋19连胜的第一局。"}},"shilin":{"t":"《事林广记》顺手炮局","w":"红方（姓名未流传）","b":"黑方（姓名未流传）","ev":"日用百科《事林广记》“饶先顺手取胜局”","d":"13世纪","pl":"中国（宋元之际）","lead":"这是宋末元初陈元靓编写的日用百科《事林广记》中收录的棋谱，被认为是现存最古老的象棋全局谱之一。这是一盘强者让对方先走的“饶先”示范局，短短9个回合，黑马就捉住了红车。","c":{"0":"这是七百多年前、宋元之际的棋谱。它收在百科全书《事林广记》讲游戏的部分，被认为是现存最古老的象棋全局记录之一。对局双方的名字没有流传下来。“饶先”是强者把先手让给弱者，所以这盘棋是在示范先走的红方怎样输掉。红方在下方，先走。","1":"红方把右边的炮移到中路。这叫“中炮（当头炮）”，正对着黑将，至今仍是最强的开局之一。可见七百年前人们就已经在下这种布局了。","2":"黑方也把炮移到中路，正面对峙。双方都动同一侧的炮，叫做“顺手炮”。炮对炮的较量，自古以来就很受欢迎。","3":"红方跳马保护中兵。中兵正被黑炮瞄着，需要有子保护。同时，这匹马也准备向前出动。","4":"黑方也跳马保护中卒。双方摆出相同的阵形，先把根基打牢。","5":"红方把右车横移一步，走到可以直冲的路线上。车是棋盘上最强的子，越早出动越好。","6":"黑方又跳出一匹马，暂时不出车。先把子力向前展开是一种思路，但车出得太晚，之后就不容易参加进攻。","7":"红车一下子过河，冲进黑方阵地。它想威胁黑子，可是红方其他子都还在家里，这样进攻有点急。也可以先出动左边的马或车。","8":"黑方挺起3路卒，给马让出道路，以后马就能向前跳。黑方几乎是在等红车过来。","9":"红车吃掉一个卒，同时瞄着后面的黑马。得了一子又捉马，看起来很痛快。可是这辆车冲得太远，身边没有帮手。孤车深入敌阵，很容易被追打。","10":"黑马向前跳出，既躲开红车，又靠近红方阵地，一步棋做了两件事。这匹马就是本局的主角。","11":"红车退一步，从侧面再捉黑马。车能远距离吃子，马一刻也不能停。不过这步棋同样没有让其他红子出动。","12":"黑马继续前进，过河进入红方阵地。每躲一次红车，它就离红帅更近一步。","13":"红方挺起一个兵，给自己的马让路。想法是接着出马，和黑马兑换。可是这就给了黑方继续前进的时间。","14":"黑方飞象，攻击红车。用防守的象赶走对方的车，非常经济。红车只好再走，黑方又赚了一步。","15":"红车横走，又吃掉一个卒。虽然多得了两个卒，但这正是输棋的一步。车离帅太远，再也回不来防守了。这里需要防备黑马，比如把车调回来。","16":"黑马跳得更深，捉住红车。不止如此：马再跳一步，就能将军红帅，同时捉住红方角上的车。一匹马同时造成了两个威胁。","17":"红车追捉黑马，可是马已经挡不住了。红帅身边已经没有任何保护。","18":"黑马跳入将军！这匹马同时还捉着红方角上的车，红帅一躲，车就会被吃掉。虽然只有9个回合，但这盘棋告诉我们：孤车冒进会有什么下场，子力要互相配合才能作战。七百年前的人们，也在同样的棋盘上思考着同样的事情。"}},"qima13":{"t":"弃马十三着（《橘中秘》）","w":"红方（姓名未流传）","b":"黑方（姓名未流传）","ev":"《橘中秘》卷上 第一局“顺炮横车破直车弃马”","d":"1632年（刊行）","pl":"中国（明）","lead":"这是明代朱晋桢于1632年（崇祯五年）刊行的棋书《橘中秘》中最开头的一局。红方故意让黑方白吃一匹马，趁机杀入，13个回合就将死对方。“弃马十三着”这个名字，在将近400年后的今天依然广为人知。","c":{"0":"这是明朝末年、1632年出版的棋书《橘中秘》的第一局。《橘中秘》和后来的《梅花谱》并称为象棋两大古典名谱。这盘棋不是实战，而是用来讲解战术的示范局，所以没有对局者的名字。红方在下方先走，只用13个回合就分出胜负。","1":"红方把右炮移到中路，正对黑将，这是“中炮”。《橘中秘》正是以深入研究中炮攻法而闻名的书。","2":"黑方也把同一侧的炮移到中路，形成炮与炮正面碰撞的“顺手炮（顺炮）”。双方都瞄着对方的中兵（中卒）。","3":"红方跳马保护中兵。既守住被黑炮瞄着的兵，马也开始发挥作用。","4":"黑方也跳马保护中卒。到这里为止，双方阵形完全一样。","5":"红方把右车向前走一步。这样下一步车就能横着走。能横向移动的车叫“横车”，好处是可以快速调到左右两边。","6":"黑方把车横移一步，变成可以直着前进的“直车”。横车对直车，两种不同用法的车互相对峙，形成“顺炮横车对直车”。","7":"红方的横车大幅移到左侧的路线上。这条路线紧挨着黑方的士，是对方防守薄弱的地方。红方准备从这里一举杀入。","8":"黑方的直车过河，深深打入红方阵地。黑方也想以对攻来对抗。不过这是一步先急于进攻、而顾不上防守的棋。","9":"红车一直冲到黑方阵地深处。这里正是象要经过的“象眼”，黑象被塞住无法行动。车紧贴着士，也离黑将非常近了。","10":"黑方把另一匹马跳到边线。这也考虑到要防止红车从侧面横插进来。","11":"这就是“弃马”的一步！红方把另一辆车抬起一步。这样一来，左角的马没有子保护，会被黑炮白白吃掉。但红方用一匹马，换来了让两辆车迅速投入进攻的时间。","12":"黑炮吃掉红马，看起来赚了一子。可是这门炮已经无法回去保护自己的阵地。一般认为，这里不吃马、而是补士巩固防守更好。","13":"红炮向前进。它把中路的黑炮当作“炮架”跳过去，瞄准后面的黑马。炮是一种隔一个子才能吃子的奇妙棋子。","14":"黑方退马逃跑。可是这匹马本来是保护中卒的重要棋子。它一走，中路防守就出现了漏洞。黑方还有别的防法，但这是最差的选择。","15":"红炮打掉中卒，将军！刚才黑马离开了，中路空空荡荡。红方的攻势从这里一下子展开。","16":"黑方补士，挡在将的前面。要解除将军，这几乎是唯一的办法。","17":"红方的第二辆车也来到同一条路线上。两辆车纵向连在一起，力量非常强大。下一步就要杀入黑方阵地深处。","18":"黑将向旁边躲开。如果不动，就会被红方两辆车在同一条直线上瞄着。","19":"红方用前车吃掉黑士，将军！这辆车马上会被另一个士吃掉，但这也在计算之中。弃掉一辆车，拆毁黑将身边的防守，真是大胆的一着。","20":"黑方用士吃掉红车。论子力，黑方已经大大领先。可是将的周围变得更加空虚。","21":"红方剩下的车移到将所在的路线上，再次将军。黑将身边几乎已经没有保护它的子了。","22":"黑方把炮垫在将前，挡住将军。这种在中间放一个子的应法叫“垫将”。","23":"红车吃掉这门炮，又将军。红车一边吃掉黑子，一边把黑将逼入绝境。","24":"黑将只能回到中间。其他位置全都被红子控制着。","25":"最后红炮来到中路，两门炮纵向重叠，将军。前面的炮当炮架，后面的炮瞄准黑将，这就是“重炮”杀。黑将无处可逃，红方获胜。只弃掉一匹马，红方就在13个回合内取胜。这盘棋四百年来一直告诉我们：比起子力多少，时间（先手）和子力的活跃更加重要。"}},"sokei1607":{"t":"现存最古老的将棋棋谱","w":"大桥宗桂（初代）","b":"本因坊算砂","ev":"有记录的最古老对局","d":"1607年（庆长12年）6月","pl":"日本（对局地点没有流传下来）","lead":"在一手一手记录下来的将棋棋谱中，这是现在保存下来的最古老的一局。先手是后来创立将棋家元大桥家的宗桂；后手是创立围棋本因坊家的算砂，他的将棋也很强。宗桂在133手时获胜。","c":{"0":"欢迎，我是Musowl。这是1607年（庆长12年）、江户时代刚刚开始时的一局。先手大桥宗桂后来被称为「一世名人」，是当时将棋第一人。后手本因坊算砂是围棋本因坊家的创始人，将棋也非常强，两人常常在众人面前对局。他们留下的平手对局共有8局，据说宗桂7胜1负。400多年前的每一手，今天仍能原样摆出来。","1":"▲7六歩。打开角的通路，这至今仍是最常见的第一手。原来400年前就已经这样开局了。","2":"△3四歩。后手也打开角的通路。双方的角隔着棋盘中央互相对望。","3":"▲4八银。先手抬起右边的银，准备让银向前走。","5":"▲4六歩。挺起4筋的步，给银腾出位置。这一手和下一手▲4七银是一套。","6":"△4二银。后手也抬起左边的银。后手的4筋聚集了防守的棋子。","10":"△4二飞。后手把飞车移到4筋。这就是现在所说的「四间飞车」，是把飞车向左移的「振飞车」之一。400年前就已经有人这样下了。","11":"▲4八飞。先手的飞车也来到4筋，双方飞车在4筋相对。不过先手之后还会多次移动飞车，寻找进攻的地方。","12":"△3三角。角上一步，为4筋增添力量。后手把4筋守得非常牢固。","16":"△6二玉。后手把王向左移。下振飞车时，通常把王藏在与飞车相反的一侧。王离战场越远越安全。","17":"▲6八玉。先手也把王向左移。之后先手的王还会走到7八、8七，更加深入。","19":"▲7八玉。王来到了7筋。接下来的目标是把金和银聚到王身边，筑起「围」。","21":"▲5八金。把右边的金靠向王。金是防守高手，有它在王身边就很安心。","24":"△5三银。后手把银走到5筋。5三银和4三银并排，中央也变得坚固。","29":"▲6七银。先手的银来到王附近。6七银和7八金一起，在王前面筑起一道墙。","30":"△6三金。后手也把金抬起，加厚王的前方。双方都在慢慢整理阵形。","33":"▲8六歩。挺起8筋的步，为王腾出位置，准备▲8七玉。","35":"▲8七玉。王来到8七。这和现在的围不一样，王待在靠近边上的高处。可以看出当时棋手的想法。","36":"△8二玉。后手的王也进入8二。双方的王各自安顿在棋盘左右的深处。","39":"▲7七桂。跳起桂马，随时可以跳到6五。这是想让围里的棋子也参加进攻的准备。","41":"▲3八飞。先手把飞车移到3筋。后手的4筋太坚固，所以先手在换一个进攻的地方。","42":"△3二飞。后手马上也把飞车移到3筋。先手的飞车去哪里，后手的飞车就跟到哪里。","43":"▲2五歩。这次挺进2筋的步，打算把飞车转到2筋，从2筋进攻。","44":"△5一角。后手把角退回。重新排列棋子，好让别的棋子能应对2筋的进攻。","45":"▲2八飞。飞车回到了原来的2筋。4筋、3筋、2筋，先手的飞车走了一大圈。","46":"△2二飞。后手又把飞车跟到2筋。不管先手把飞车转到哪里，后手都在同一条筋上迎战。这场「飞车追逐」是本局序盘的看点。","47":"▲6五歩。这时先手从没有飞车的6筋开战。不在双方飞车对峙的地方，而是攻击对方薄弱之处。中盘开始了。","49":"▲6四歩。用步冲上去吃掉对方的步。目的是把后手的金引出来，让王身边的防守松动。","50":"△同金。后手用金吃回。金稍稍离开了王，后手的防守出现了一点空隙。","51":"▲4五歩。接着挺进4筋的步，也在摇动后手4筋的防守。","53":"▲3七桂。另一只桂马也跳起来加入进攻。先手的进攻棋子一个个向前了。","54":"△6五歩。后手把手里的步打在6五，堵住先手桂马要跳去的格子。步虽然便宜，却很适合堵住对方棋子的去路。","56":"△7五歩。后手开始反击，戳先手王正上方的那一筋。王头上的步被打乱，王就难守了。","57":"▲同歩。先手用步吃掉。如果不吃，后手的步就会挺到7六。","58":"△同金。后手用金吃回，金来到7五。后手把金推到前面，逼近先手的王。","59":"▲7六歩。先手打下手里的步，挡住金的前进。这一枚步守护着王头。","61":"▲6九飞。先手的飞车一直走到6筋最下面，要把飞车的力量加到6筋的战斗中。这只飞车后来会被后手的银吃掉。","63":"▲6五桂。7七的桂马跳出去吃掉6五的步。早早准备好的桂马终于发挥作用了。","64":"△同桂。后手也用桂马吃回，双方交换了桂马。","66":"△8五歩。后手也从8筋逼近，想把先手王前面的步一个个剥掉。","68":"△7七歩。后手把步打在紧挨着王的7七。吃掉它，吃的棋子就会被引开；不吃，步就会升变。这是用小小的步打乱防守的常见手筋。","69":"▲7九金。先手把金退开。现在不吃步，而是选择保持防守的形状。","70":"△7五桂，将军。后手打下桂马。桂马能越过其他棋子攻到8七的王。后手的进攻越来越强了。","72":"△同银。先手的步吃掉桂马后，后手用银吃回并向前进。后手的进攻棋子已经来到先手的王旁边。","74":"△8六歩，将军。后手再打下一步，就在8七王的眼前。王已经待不住了。","75":"▲9八玉。先手的王逃到边上的9八，离开危险的地方，重新整理防守。","77":"▲7五歩。这时先手用7六的步吃掉了7五的银。吃掉后手进攻的核心，抓住反击的机会。","79":"▲7六银。先手打下手里的银，与7五的金相碰。既守住王头，又想赶走后手的金。","81":"▲同银。银和金互相交换。先手正把后手的进攻棋子一个个减少。","83":"▲6五歩。6六的步吃掉了6五的桂马。后手又少了一个进攻棋子，先手手里的棋子越来越多。","84":"△7八银。后手打下银，瞄准6九的飞车。先手会被吃掉飞车，但趁这段时间加紧自己的进攻。","85":"▲9二歩。从这里开始先手反击。在后手王附近的9二打步，把香车引到前面。让王身边的棋子移动，制造空隙，这是常见的手筋。","86":"△同香。后手用香车吃掉步。但这样香车来到9二，成了下一手桂马的目标。","87":"▲8四桂。打下桂马，同时瞄准9二的香车和7二的金。一次攻击两个目标，正是桂马的拿手好戏。","88":"△5一角。后手退角，沿斜线瞄准8四的桂马，想吃掉桂马阻止进攻。","89":"▲7四桂，将军。先手打下另一只桂马将军。桂马能越过其他棋子将军，很难防守。","90":"△8三玉。后手的王向上逃。王向前走，也就靠近了先手的桂马。","91":"▲9二桂成。8四的桂马吃掉香车并升变，成为走法和金一样的「成桂」。先手的棋子攻入了后手王的附近。","92":"△同玉。后手用王吃掉成桂。后手的王来到了边上的9二。","93":"▲7七角。先手的角吃掉7七的步。一直没动的角终于开始发挥作用，后来它会立下大功。","94":"△6九银成。后手用银吃掉先手的飞车并升变。被吃飞车是很大的损失，但先手判断自己攻王更快。","95":"▲同金。用金吃回成银。先手防守的金还稳稳地留着。","97":"▲9三歩，将军。步虽然便宜，打在王的眼前却很有力。","98":"△8一玉。后手的王退到8一，逃路越来越少了。","99":"▲8六角。用角吃掉8六的步。这只角沿着斜线一直看到后手阵地深处，是在为下一步大棋做准备。","101":"▲9二金，将军。9二的金和9三的步合力，把后手的王从边上赶出去。","103":"▲5三角成。8六的角一口气走到5三并升变为「马」。马在角的走法上再加上周围一格的走法，是很强的棋子。先手的大子攻到了后手王的附近。","104":"△6一玉。后手的王再逃向6筋。王正从边上被赶向棋盘中央。","105":"▲6四香。打下香车。香车可以笔直向前一直走，盯住整条6筋。","106":"△6二歩。后手打步，堵住香车的通路。","107":"▲4三马。用马吃掉4三的银。后手又少了一个防守棋子。","108":"△5二桂。后手打下桂马加固防守。形势很苦，但后手仍在坚持。","109":"▲8七玉。这时先手把自己的王上到8七。看来是在后手反击之前，让王有更宽的活动空间。","110":"△8九飞，将军。后手反击，打下手里的飞车将军。后手也想抓住先手的王。","112":"△7七歩成，将军。步升变为「と金」并将军。と金走法和金一样，被吃掉时对方却只得到一枚步。","114":"△6九飞成。飞车吃掉金，变成「龙」。先手王身边的防守没有了，比赛变成谁先抓住对方的王的竞赛。","115":"▲5三银。先手打下银，收紧对后手王的包围。即使自己的王危险，也要下逼近对方王的棋，这正是胜负的关键。","116":"△6六银，将军。后手也打银将军，先手的王必须逃走。","117":"▲8六玉。王逃到8六。先手的王向上有很宽的逃路。","119":"▲9五玉。王继续逃到边上的9五。到了这里，后手的棋子很难够到。先手的王暂时安全了，可以专心进攻。","120":"△6三歩。后手挺步防守。但后手的防守已经不够了。","121":"▲6二银。从这里开始先手收官（寄せ）。打入银，去吃后手王身边的防守棋子。","122":"△同角。后手用角吃掉银。","123":"▲同银成。5三的银吃掉角并升变。后手少了一个大子。","125":"▲同桂成。7四的桂马也吃掉金并升变。先手一边交换，一边把后手的防守一层层剥掉。","126":"△同玉。后手用王吃掉。但后手王的身边几乎没有防守棋子了。","127":"▲5三角，将军。马上把吃来的角打下去将军。吃来的棋子能立刻使用，这正是将棋的有趣之处。","129":"▲8四金，将军。打下金，从上面堵住后手王的逃路。","131":"▲7三歩，将军。后手的王只能再退回深处。","133":"▲6三香成。香车吃掉6三的步并升变。算砂看出下一手棋子进入6二后王就无路可逃，于是在这里认输。宗桂133手获胜。本局的看点是序盘的「飞车追逐」、中盘用步和桂马的拉锯，以及终盘宁可被吃飞车也优先攻王的判断。这一局让我们看到，400年前名人的想法和今天的将棋是相通的。"}},"hu1960":{"t":"15岁的胡荣华击败杨官璘","w":"杨官璘","b":"胡荣华","ev":"第五届全国象棋个人赛 第三轮","d":"1960年10月28日","pl":"北京","lead":"这是初次参加全国比赛的15岁少年胡荣华，以后手挑战三届全国冠军杨官璘的一局。胡荣华在开局阶段弃炮夺取主动，又把漫长的残局赢了下来。这届比赛胡荣华夺得冠军，此后实现全国个人赛十连霸，这盘棋被称为宣告“新老棋王交接”的名局。","c":{"0":"这是1960年在北京举行的第五届全国象棋个人赛第三轮。红方是杨官璘，他在1956年第一届比赛中夺冠，此前四届比赛中三次获得冠军，是当时最强的棋手。黑方是上海的胡荣华，年仅15岁，第一次参加全国比赛。人人都以为红方会赢，可这盘棋却改写了象棋的历史。","1":"杨官璘把右炮移到中路。中炮正对黑将，是杨官璘研究最深、最拿手的开局。","2":"胡荣华跳马保护中卒。早早出马，为防守和进攻都做好准备。","3":"红方也跳马，一边保护中兵，一边把子力向前展开。双方都先把中路守稳。","4":"黑方早早挺起7路卒。既限制红马前进，又给自己的马让出道路。在这个局面，大多数人会先出车。","5":"红方把右车横移一步，走到可以直冲的路线上。","6":"黑方也把车横移出来。双方都想让最强的车尽早发挥作用。","7":"这时红方挺兵。很多人会走车过河，但杨官璘想把局面引向自己最拿手的炮的用法。","8":"黑炮进到河口，挡在红方右车的前面。这叫“左炮封车”，把红车关在家里。为了不让杨官璘走成拿手的阵形，这是一个大胆的构思。","9":"红方跳出另一匹马，发展左翼，准备反击。","10":"黑方飞象，巩固防守。象不能过河，它的任务是守护将的周围。","11":"红炮冲入黑方阵地深处，打掉马并将军！这是用炮换马。开局时炮换马常常吃亏一步，但这里据说是不错的一着。","12":"黑方用车吃回红炮。子力又恢复平衡，黑车也自然地出动了。","13":"红方把左车也开出来。红方希望赶走黑炮，让车前进。","14":"黑方另一门炮也进到河口，挡住红方左车。这样红方两辆车的前面都被炮封住了，红方变得很难走。","15":"红马向河口前进。红方有两个打算：用马吃中卒，或者挺兵攻击黑炮。","16":"黑方补士守住中路，先防住红马吃中卒将军的手段。","17":"红方挺兵。原来被兵挡住的马路打开了，红马可以吃黑炮了，黑炮受到攻击。","18":"这是整盘棋最有名的场面。黑方不保炮，而是进车攻击红马，宁可弃掉一门炮也要保持进攻的阵形。对手是三届冠军，自己只有15岁，胡荣华却选择了气势而不是子力，观众们都大吃一惊。","19":"红马吃掉黑炮，黑方少了一子。作为交换，黑车从侧面牵制住了红方的车和马。","20":"黑方另一门炮打掉中兵，将军！黑方的反击从这里开始。红方只能补士来保护帅。","21":"红方补士挡住将军。可是黑炮仍然深深地留在红方阵地里。","22":"黑车吃掉红车。刚才炮移开以后，车的通路就打开了。","23":"红方用马吃回黑车，双方兑掉一车。黑方仍少一子，但子力更加活跃。","24":"黑马进到河口。下一步也有去吃红马的打算。","26":"黑炮横移，正好停在红马旁边。象棋的马，如果在要走的方向紧挨着有子，就不能往那边走（蹩马腿）。黑炮蹩住了马腿，红马很难动弹。","28":"黑方挺起中卒。后来这个卒会成为攻入红方阵地的重要棋子。","30":"黑马吃掉一个兵，钻进红方阵地。黑方一点一点地把子力追回来。","32":"黑马退回中路，避免和红马兑换，占据中间的好位置。","34":"黑炮退一步，准备接着横移去攻击红马。","36":"黑炮横移，以自己的车为炮架，瞄准红马。炮要隔一个子才能吃子。","38":"黑马跳出，攻击红车。这匹马一离开，原来瞄着黑车的红炮也就没有炮架了。","40":"红炮将军，黑方落士挡住。红方也在拼命反击。","42":"黑炮吃掉红马！开局弃掉的炮在这里追了回来。子力平衡，黑方还多一个卒，而且三个进攻的子都已过河。黑方明显占优了。","44":"黑方挺卒，白白送给红方。红方如果吃掉，黑方隐藏的计划就能实现了，这是一步看得很远的棋。","45":"红方用相吃卒。现在红方必须小心黑方的计划。","46":"黑方又把马送上。红马如果吃掉它，黑炮就能一边将军，一边亮出对红车的攻击。","47":"红方没有吃马，而是把自己的马退了回来。不愧是杨官璘，不会轻易上当。","48":"黑车横移，摆脱了牵制。这样车又能自由行动，进可攻、退可守。","50":"黑炮来到中路，正对红帅，这是非常强的位置。","52":"黑马再次前进。炮和马在中路配合作战。","56":"黑马一直走到边线，瞄着红帅的侧面。边马能走的地方不多，但在这里它肩负着威胁红帅防线的重要任务。","58":"黑方的中卒继续前进，逼近红方阵地。过了河的卒还能横着走，力量大大增强。","60":"双方的炮互相兑掉了。红炮吃掉黑炮，黑卒又把红炮吃回。黑卒已经来到红方阵地附近。","62":"黑车吃掉红方一个相，红方的防守又少了一层。","64":"黑马将军！红方用车蹩住马腿来解将。象棋里，在马旁边放一个子，就能挡住马的将军。","66":"黑马先退一步。它一边不断将军，一边寻找最好的位置。","70":"黑马又将军。红车离不开帅的身边，无法参加进攻。","72":"黑马退到边上，继续牵制红车，同时考虑下一步计划。","76":"黑车把红方另一个相也吃掉了。红帅身边变得非常冷清。","82":"黑车吃掉红马。一直努力作战的红马，在这里被兑掉了。","83":"红方也用车吃回黑马。双方兑掉马以后，棋盘清爽多了。接下来是双方以车和兵卒为主的战斗。","90":"黑卒吃掉红方一个仕！卒虽然是小子，但深入敌阵以后，力量大到可以换掉一个士。","91":"红方用另一个仕吃回黑卒。一卒换一仕，红帅的防守更薄了。","92":"黑车吃掉一个红兵。在残局里，剩下的兵卒数量决定胜负。","98":"黑车又吃掉一个兵。红方的兵所剩无几。黑方一步一步地走向更容易取胜的局面。","99":"红车也吃掉黑方一个象作为回击。双方的车你来我往，各吃一子。","104":"黑方开始挺进边卒。把这个卒送到红方阵地深处，就是黑方的取胜之路。","112":"黑车绕到卒的后面保护它。车和卒配合起来，是非常强的组合。","115":"红车吃掉黑方一个卒，黑方只剩一个卒了。红方也还没有放弃。","123":"红方挺兵前进。可是一般认为，这里退车保护帅会更好。这一步成了胜负的分水岭。","124":"黑卒横移，靠近红帅。卒每次只能走一步，但离帅越近，就越可怕。","126":"黑车退下来，攻击红兵。如果不看住这个兵，红方也可能用它来反击。","134":"红兵走到了棋盘的尽头，但黑车一路紧追不放。走到敌方底线的兵已经不能再前进，只能横着走。","136":"黑车吃掉了红方最后一个兵。黑方有车、卒和双士，红方只有车和单仕。多一个卒的黑方，胜利已经清楚可见。","140":"黑车将军！红帅只能后退。","144":"黑卒继续前进，来到了红帅的身边。卒和车联手，红帅周围已经不再安全。","148":"黑将也横移一步。在残局中，将（帅）也是重要的战斗力，可以限制对方棋子的行动。","150":"黑车退下来，攻守兼备。这是为最后的绝杀，把车调到最好位置的准备。","152":"黑车进入4路，红方再也守不住了。胜负已定，15岁的胡荣华获胜。开局大胆弃炮，中局马炮配合，残局精准地赢到底——这盘棋三者兼备。胡荣华赢得了这届比赛，此后从1960年到1979年连续十次获得全国冠军，完成了“十连霸”。"}},"soei1790":{"t":"鬼宗英平手战胜名人","w":"大桥宗英（六代）","b":"大桥宗桂（九代）","ev":"御城将棋（每年一次在江户城举行的对局）","d":"1790年（宽政2年）","pl":"日本（江户）","lead":"被称为「鬼宗英」的大桥宗英，在御城将棋中与当时的名人九代大桥宗桂下了这盘平手棋。那一年两人交替下平手和让香，这盘平手棋被誉为「稀世名局」。宗英在121手获胜。","c":{"0":"我是Musowl。御城将棋是将棋家元们每年一次在将军面前对局的盛大场合。先手大桥宗英因为太强被称为「鬼宗英」，后来成为九世名人。后手九代大桥宗桂前一年刚刚成为名人。这是名人对未来名人的较量。宗英推广了先筑好防守再进攻、接近现代将棋的思路，也被称为「近代将棋之祖」。","1":"▲7六歩。打开角路的第一手。先手宗英从这里开始，计划用右边的棋子进攻。","3":"▲2六歩。挺起飞车前面的步。早早挺进飞车先的步给对方施压，是宗英重视的想法之一。","4":"△4四歩。后手挺起挡住自己角路的步。避开角的交换，准备慢慢地下。","5":"▲4八银。抬起右边的银，让它既能进攻也能防守。","7":"▲5六歩。挺起中央的步，让银和金更容易向前。","9":"▲3六歩。也挺起3筋的步，给桂马开出跳跃的路，准备下一手▲3七桂。","11":"▲2五歩。飞车先的步继续前进。后手必须用角或银守住2筋。","12":"△3三角。用角守住2筋。如果不守，先手会走▲2四歩，飞车从2筋突破。","15":"▲5八金。把金靠近王，开始加固防守。","17":"▲3七桂。跳起桂马，进攻的形状完成了。桂马可以跳到4五或2五，逼近对方阵地。","20":"△5二飞。后手把飞车移到中央的5筋，就是现在说的「中飞车」，目的是从中央动摇先手的阵地。","22":"△5五歩。立刻冲撞5筋的步。正像中飞车的风格，在中央开战。","23":"▲同歩。先手吃掉步。如果不吃，后手的步会吃掉5六的步。","24":"△6四银。后手把银向前，准备吃回5五的步。","25":"▲5四歩。先手把吃来的步再往前推。把步推到后手飞车的眼前让对方吃，借此打乱对方棋子的位置。","26":"△同飞。后手用飞车吃步。后手的飞车出到5四，在中央很有力量。","27":"▲7九角。先手退角。先退一步，以后可以从另一条斜线发挥作用。这只角后来会出到2四。","28":"△4一玉。后手把王移到4一。下中飞车时，通常把王藏到右边。","29":"▲5六歩。打步，挡住后手飞车沿5筋前进。","30":"△5五歩。后手也打步，在5筋再次相撞。中央的拉锯还在继续。","32":"△5六歩。用步吃步，攻入先手阵地。","34":"△5五银。后手出银，想掌握5筋的主动。","35":"▲同金。先手用金吃掉银，金和银要交换了。","36":"△同飞。后手用飞车吃回金。金银交换之后，中央的战斗暂时平静。先手手里有银，后手手里有金。","37":"▲5六歩。先手打步堵住5筋，不让后手的飞车再进来。","38":"△5二飞。后手退回飞车。中央的战斗到这里告一段落。","39":"▲5八金。先手把另一枚金抬起，加固王的周围。","41":"▲6九玉。先手的王开始向左移动，远离发生战斗的中央。","43":"▲7八玉。王来到7八。接下来要用金银筑围。宗英是重视「先守后攻」的棋士。","44":"△8二飞。后手把飞车移回原来的8筋。中央平静了，这次想从8筋进攻。","45":"▲7七银。先手打下手里的银守在王前，事先防备后手从8筋来的进攻。","47":"▲1六歩。挺起边上的步。边步先挺好，以后从边上进攻或王要逃跑时都有用。","49":"▲1五歩。边步再前进一格，先手在细心地做准备。","51":"▲2四歩。先手在这里发动进攻，冲撞一直挺进的飞车先的步。先手的攻势开始了。","53":"▲同角。退到7九的角沿斜线一口气出到2四。到这里就明白第27手退角的意义了。","54":"△同角。后手用角吃角，角互相交换。","55":"▲同飞。先手用飞车吃回，飞车出到2四，盯着后手的阵地。双方手里各有一只角。","56":"△2三歩。后手打步，挡住飞车的去路。","57":"▲2六飞。先手退回飞车，不深追，把飞车放回安全的地方。","59":"▲4六歩。挺起4筋的步，为下一步进攻做准备。2筋之后，先手打算从3筋和4筋进攻。","60":"△8四飞。后手把飞车浮起，也能横向使用。","61":"▲3五歩。挺进3筋的步，准备和后手3四的步相撞。","63":"▲4五歩。冲撞4筋的步。先手在3筋、4筋、5筋好几条筋上同时摇动对方。","65":"▲5五歩。5筋的步也向前，在后手防守的中央打进一个楔子。","66":"△5三歩。后手打步守住5筋。","67":"▲3四歩。先手的步吃掉3四的步。这枚步之后会在3三升变，逼近后手的王。","68":"△8六歩。后手也反击，冲撞8筋的步，在先手王的附近点火。","69":"▲同银。先手用银吃步。7七的银向前，一边保护王一边应对。","70":"△4四角。后手打下手里的角。这只角沿斜线盯着先手阵地，攻守都能发挥作用。","71":"▲2九飞。先手把飞车一直退到最下面，避开后手角的斜线，同时继续盯住2筋。","72":"△6五歩。后手挺进6筋的步，摇动先手王的附近。","74":"△3六歩。后手打步，瞄准3七的桂马。","75":"▲6六角。打下手里的角。这只角沿斜线瞄着8四的飞车。既防守又攻击对方大子，一举两得。","76":"△8一飞。后手让飞车逃走。先手一手角，就把后手的飞车赶到了最下面。","77":"▲4五桂。桂马跳起吃掉4五的步。下一步准备跳进3三或5三。","78":"△4六金。后手打金，从桂马后面逼近。","79":"▲3三歩成。3四的步进到3三，升变为「と金」。先手的棋子攻进了后手王的附近。","80":"△同桂。后手用桂马吃掉と金。","81":"▲同桂成。先手用4五的桂马吃掉那只桂马并升变。一边交换，一边减少后手王周围的棋子。","82":"△同角。后手用角吃回成桂。","83":"▲5七银。先手把银上到5七，与后手4六的金相碰，要赶走逼近的金。","85":"▲同金。银和金互相吃掉。先手把攻进自己阵地的后手棋子清理得干干净净。","86":"△7五歩。后手挺进7筋的步，瞄准先手的王头。","87":"▲4五桂。再次打下桂马。这只桂马瞄准3三的角。","88":"△2四角。后手把角逃到2四。","89":"▲3三歩。打步，在后手王附近打进楔子。","90":"△2二金。后手退金防守。","91":"▲5四歩。5筋的步继续前进，把后手的银引到5四。","92":"△同银。后手用银吃步。但这样4三就空了，和先手接下来的棋连在一起。","93":"▲2四飞。这是胜负的分水岭。先手用飞车吃掉后手的角。即使交出飞车，先手判断在这段时间里可以一口气逼近后手的王。","94":"△同歩。后手用步吃掉飞车。先手交出了飞车，却得到了角这枚进攻的棋子。","95":"▲3二角，将军。打下角将军。接着▲2四飞，这是先手进攻的正式开始。","96":"△5一玉。后手的王逃到5一。","97":"▲5四角成。角吃掉5四的银并升变为「马」。因为4三是空的，角沿斜线直接走到。第92手△同银让4三空出来，在这里起了作用。","98":"△同歩。后手用步吃掉马。先手交出了所有大子，但后手防守的银也没了。","99":"▲5三歩。在后手王的眼前打步，建立立足点。下一步准备在5二升变。","100":"△4八飞。后手也反击，把得到的飞车打进先手阵地。比赛变成谁的进攻更快的竞赛。","101":"▲5八银。先手退银防守，挡住后手飞车横向逼近王。","102":"△5六角，将军。后手打下角。从5六沿斜线经过6七，攻到7八的王。","103":"▲8八玉。先手把王退一格，离开角的斜线。下一手防守棋，确保不在对攻中落后。","104":"△4五角。后手的角吃掉桂马。","105":"▲5二歩成。步升变为と金，吃掉后手的金。先手的棋子来到了后手王的旁边。","106":"△同玉。后手用王吃掉と金。","107":"▲5三歩，将军。步可以一再打下，所以能这样连续将军（不过同一条筋上不能有两枚自己未升变的步）。","108":"△6二玉。后手的王逃到6二。","109":"▲6四银。打下银，堵住后手王的逃路。","110":"△7四银。后手也打银防守。","111":"▲5二歩成。做出と金，从后面也攻击后手的王。","112":"△7二玉。后手的王走到7二，一步步被赶向边上。","113":"▲7三银成。银吃掉7三的桂马并升变。后手王的守卫又少了一个。","114":"△同玉。后手用王吃掉成银。","115":"▲6四金，将军。从这里开始，先手用手里的棋子追捕后手的王。","116":"△8三玉。后手的王走到8三。","117":"▲7四金，将军。金吃掉7四的银并将军，拿掉后手王周围的守卫。","118":"△同玉。后手用王吃掉金。后手的王被拉向棋盘中央。","119":"▲7五银，将军。8六的银吃步将军。第69手为了防守而上去的银，最后也加入了进攻。","120":"△6三玉。后手的王逃到6三。","121":"▲6四银，将军。7五的银进到6四将军。先手手里还有金、银、桂，宗桂看出王已无法逃脱，于是在这里认输。宗英121手获胜。中央战斗之后先把王围好，然后把进攻扩展到2筋、3筋、4筋，最后弃飞车一口气收官。这是一盘充分展现宗英「先守后攻」风格的名人名局。"}},"soho1856":{"t":"棋圣宗步的「远见之角」","w":"天野宗步","b":"伊藤宗印（八代）","ev":"御城将棋（每年一次在江户城举行的对局）","d":"1856年（安政3年）","pl":"日本（江户）","lead":"被称为「棋圣」的天野宗步，与后来成为名人的八代伊藤宗印下了这盘御城将棋，这也是宗步最后一次御城将棋。第33手他把角打在自己阵地角落的▲1八角，作为将棋史上的名手流传至今。宗步111手获胜。","c":{"0":"我是Musowl。天野宗步是江户时代末期的棋士，因为太强，被称为「实力十三段」「棋圣」。但他不是将棋家元家族出身，所以没能成为名人。后手八代伊藤宗印是宗步的师弟，后来成为名人。1856年的这次御城将棋，是宗步下的最后一次御城将棋。据说宗步是用角的高手，请留意本局中的角。","1":"▲7六歩。打开角路的第一手。宗步的角将是本局的主角。","3":"▲2六歩。挺起飞车前的步。宗步擅长尽早挺进飞车先的步、让棋子动起来的快节奏序盘。","4":"△5四歩。后手挺起中央的步。可以看出之后要把飞车移到5筋的中飞车作战。","7":"▲4八银。抬起右边的银，为攻守做准备。","11":"▲2五歩。飞车先的步继续前进，下一步准备在2四冲撞。","12":"△6四银。后手把银向前。打算把银推向5五，从中央进攻。","13":"▲2四歩。冲撞步，去交换飞车先的步。这是现在也常见的自然开战方式。","15":"▲同飞。用飞车吃步。先手手里多了一枚步，飞车也向前了。交换飞车先的步，手里的步会增加，飞车也更好用。","16":"△5二飞。后手把飞车移到5筋。下中飞车，准备从中央反击。","17":"▲6九玉。先手把王向左移，远离中飞车要进攻的中央。","19":"▲2八飞。飞车回到原位。已经得了一步，这里冷静地退回飞车。","20":"△2三歩。后手打步，堵住2筋的空隙。","21":"▲2二角成。这时先手交换了角。交换之后，双方手里都有角，可以打在任何地方。宗步接下来就要展示把手里的角打在哪里的本领。","22":"△同银。后手用银吃回。双方手里各有一只角。","24":"△5五歩。后手冲撞中央的步，这是中飞车典型的进攻。","26":"△同银。后手的银来到5五。后手的棋子在中央越来越强。","27":"▲5四歩。先手把步打进后手阵地。5四的步挡在后手飞车前面，妨碍后手棋子的行动。","29":"▲5三角。先手把手里的角打进后手阵地，想让它在后手阵中大闹一场。","30":"△4四角。后手也打角，与先手的角相碰。这是想消掉先手角的防守手。","31":"▲同角成。先手的角吃掉后手的角并升变。","32":"△同银。后手用银吃回马。角又交换了一次，先手手里又有了角。","33":"▲1八角。这就是著名的场面。宗步把手里的角打在自己阵地角落的1八。这只角沿着斜线，一直望到棋盘另一边的后手阵地。现在它从后面支撑着5四的步，等以后斜线打开时再大显身手，这就是「远见之角」。它被称为将棋史上的名手，不过后来的名人中也有人认为，这可能是困难局面中苦心想出的一手。","34":"△4二金。后手把金靠过来，加固王的周围。","35":"▲5七银。先手抬起银，准备中央的战斗。","37":"▲5六银。银继续向前，瞄准中央的5五和4五一带。","39":"▲5八飞。把飞车移到中央。先手也摆出类似中飞车的形状，在5筋集中力量。","41":"▲6六歩。挺起6筋的步，为银和角开路。","43":"▲7九玉。王再向左边深处移动。宗步也在进攻前先整理好王的防守。","45":"▲5九金。把金靠近王，加固防守。","46":"△8五歩。后手挺进8筋的步，准备从先手王的附近进攻。","47":"▲2七角。1八的角上了一格。稍稍移动角的线路，瞄准4五和3六。","49":"▲4五银。银前进到4五，逼近后手阵地。2七的角从后面支撑着这只银。","50":"△5五歩。后手打步，堵住中央。","52":"△8六歩。后手在8筋开战，冲撞先手王附近的步。","54":"△7五歩。后手也冲撞7筋的步，想把先手王前面的步打乱好几枚。","56":"△4五银。后手的银吃掉了4五先手的银。","57":"▲同角。2七的角吃回4五的银。角的斜线在这里派上了用场。","58":"△4四银。后手抬起银，追赶4五的角。","59":"▲1八角。角又回到了角落的1八。被银追赶后，回到从远处瞪视的原来位置。请看这只角最后如何发挥作用。","60":"△5六银。后手打入银，从中央进攻。","61":"▲同银。先手用银吃掉。","62":"△同歩。后手用步吃回，步来到5六。","63":"▲同飞。先手用飞车吃步。飞车在中央发挥作用。","64":"△5五银。后手再打银，追赶先手的飞车。","65":"▲5八飞。飞车退回原位。","66":"△6六银。后手的银吃掉6六的步，逼近先手的王。后手的进攻还在继续。","67":"▲6七歩。先手打步，不让银再进来。","68":"△7七歩。后手在先手王附近的7七打步，想移动棋子制造空隙。","69":"▲同桂。先手用桂马吃步。这只桂马之后会跳到6五参加进攻。","70":"△7五银。后手的银吃掉7五的步，逼近先手的王头。","71":"▲6八金。先手把金靠过来守王。","72":"△7六歩。后手再打步，瞄准桂马。后手的进攻越来越凌厉。","73":"▲6五桂。先手在这里反击。桂马跳到6五，瞄准后手阵地的5三。","74":"△6四银。后手退银，瞄准6五的桂马。","75":"▲5三银。先手把手里的银打入后手阵地。5四的步和6五的桂马都支撑着这只银。很早以前打下的5四步在这里派上了用场。","76":"△同金。后手用金吃银。","77":"▲同歩成。5四的步吃掉金并升变为と金。","78":"△同银。后手用银吃掉と金。","79":"▲同桂成。6五的桂马吃掉那只银并升变。互相吃子继续，后手阵地的棋子越来越少。","80":"△同银。后手用银吃掉成桂。可是5四的先手步已经不在了，1八角的斜线一直通到了6三。","81":"▲6三角成。1八的角终于动了。它沿斜线一口气前进，吃掉6三的步，变成了「马」。第33手打下的「远见之角」，在48手之后发挥了巨大作用。这是从棋盘一端跑到另一端、最像角的一手。","82":"△7七银。后手打银逼近先手的王，后手也不甘示弱。","83":"▲2四歩。先手在2筋打步，摇动后手王的附近。","84":"△同歩。后手用步吃掉。","85":"▲2五歩。再打一步，瞄准后手2四的步，想撬开2筋。","86":"△3三角。后手打角加固防守。","87":"▲5五歩。打步，压制后手银和角的行动。","88":"△7八银成。后手的银吃掉先手的金并升变。","89":"▲同金。先手用金吃回。","90":"△7七金。后手打金，逼近先手的王。先手王的附近也变成了激烈的战斗。","91":"▲4五银。先手打银，这只银瞄准后手王附近的3四。","92":"△6一飞。后手把飞车移到6筋，瞄准先手的马。","93":"▲7四马。马躲到7四。马在自己阵地和对方阵地都能发挥作用，是很强的棋子。","94":"△2五歩。后手用步吃掉2五的步。","95":"▲3四银。银吃掉3四的步，先手的银来到后手王的正前方。","96":"△2四角。后手把角移到2四，防备先手的进攻。","97":"▲4六银。再打一枚银，切断2四角的斜线，压制后手角的作用。","98":"△3三金。后手打金防守。","99":"▲同银成。3四的银吃掉金并升变。","100":"△同玉。后手用王吃掉成银。后手的王来到了防守棋子很少的3三。","101":"▲3五银。再打一枚银。这只银瞄准2四的角，也堵住了后手王的逃路。","102":"△8七桂，将军。后手打桂将军，这是最后的挣扎。","103":"▲同金。先手用金吃掉桂马。","104":"△同金。后手用金吃回。但先手的王还没有被抓住。","105":"▲2四银，将军。银吃掉角并将军。从这里开始一口气追捕后手的王。","106":"△同玉。后手用王吃掉银。","107":"▲3五银，将军。4六的银进到3五将军，把后手的王从自己阵地里拉出来。","108":"△同玉。后手的王吃掉银，出到3五。王来到棋盘中央附近而又没有守卫，就非常危险。","109":"▲4六角，将军。最后还是角。打下手里的角将军。宗步的这盘棋，角从头到尾都是主角。","110":"△4四玉。后手的王逃到4四。","111":"▲3四金，将军。宗印看出王已经无法逃脱，于是在这里认输。宗步111手获胜。第33手的▲1八角，在48手后的▲6三角成大显身手，最后也是用角将军决定胜负。这是一盘能清楚看出宗步看得很远、提前布子思路的名局。"}},"sakata1913":{"t":"阪田三吉用袖飞车击败关根","w":"阪田三吉","b":"关根金次郎","ev":"大阪朝日新闻主办的对局","d":"1913年（大正2年）7月14日","pl":"日本（大阪）","lead":"大阪的阪田三吉，与后来成为十三世名人的关根金次郎，是一生的对手。这是两人1913年夏天在大阪下的一盘平手棋。阪田用把飞车移到3筋的「袖飞车」进攻，赢下了143手的漫长战斗。","c":{"0":"我是Musowl。阪田三吉出生在大阪附近的堺，几乎靠自学学会将棋，成为关西最强的棋士。关根金次郎是东京的第一人，后来成为十三世名人。两人从年轻时就多次交手，一生对局超过30盘，是有名的对手。这一年4月，阪田第一次去东京和关根对局。据说「银在哭泣」这句话就出自那盘让香棋，而这盘7月的对局，是和来到大阪的关根下的平手棋。","1":"▲7六歩。打开角路的第一手。阪田之后会组成充满自己创意的作战。","3":"▲5六歩。挺起中央的步，准备把银上到5七。","5":"▲6六歩。也挺起6筋的步，挡住了角路。避免角的交换，慢慢地布阵。","9":"▲6七银。把银上到王的前面，开始筑防守的墙。","11":"▲7七角。角上一格，放在6六步的后面。用角来防守，是接近「矢仓」的形状。","13":"▲4八银。另一只银也抬起来，准备用来进攻。","16":"△4二玉。后手关根把王移向右边。","17":"▲7八金。把金靠向王，加固防守。","19":"▲3六歩。挺起3筋的步。这里就是阪田作战的起点。","21":"▲3八飞。把飞车移到3筋，这就是「袖飞车」。飞车不放在2筋，而是放在旁边的3筋，从3筋进攻。阪田常用这样独特的作战。","23":"▲6九玉。先手的王向左，远离要进攻的3筋。","26":"△3二玉。后手的王到了3二。可是这里就在先手飞车瞄准的3筋旁边。","27":"▲3五歩。袖飞车的进攻开始了。冲撞3筋的步，想用飞车从3筋突破。","28":"△同歩。后手用步吃掉。","29":"▲同飞。飞车吃步。先手的飞车出到3五，盯着后手王的附近，还得了一枚步。","30":"△3一角。后手退角，准备守住3筋。","31":"▲3八飞。先手退回飞车。已经得了一步，就冷静地把飞车放回去。","32":"△8六歩。后手在8筋反击。","34":"△同角。退到3一的角沿斜线一直走到8六吃步。巧妙地利用了角的长斜线。","35":"▲同角。先手用角吃角。","36":"△同飞。后手用飞车吃回，角互相交换了。","37":"▲8七歩。打步，追赶后手的飞车。","38":"△8二飞。后手的飞车回到原位。双方手里各有一只角。","39":"▲4六银。银向前，准备中央和4筋的战斗。","43":"▲7九玉。先手把王放得更深，整理防守。","47":"▲8八玉。王安顿在8八，金和银聚集在王的周围。","51":"▲5五歩。冲撞中央的步，真正的战斗从这里开始。","52":"△同歩。后手用步吃掉。","53":"▲6三角。把手里的角打进后手阵地，想让它在后手阵中大闹。","55":"▲5八飞。把飞车移到5筋，加入中央的战斗。","56":"△9二角。后手也打角，这只角沿斜线瞪着先手阵地。","57":"▲3六角成。6三的角沿斜线退回，离开敌阵时升变，在3六成为「马」。回到自己阵地的马，攻守都能发挥作用。马在自己阵地里，是非常可靠的防守棋子。","58":"△4五歩。后手挺步，追赶4六的银。","59":"▲5七银。银退到5七。","60":"△7六歩。后手用7筋的步吃掉先手王前面的步。","61":"▲同银。先手用银吃回。","62":"△5四银。后手把银出到中央，加固防守。","63":"▲3七马。马退一格，守护自己的阵地。","64":"△7二飞。后手把飞车移到7筋，瞄准先手的王头。","65":"▲7五歩。打步，堵住后手飞车的通路。","66":"△4四金。后手抬起金。","68":"△4三玉。后手的王上到4三。王来到靠近棋盘中央的地方，这是少见的形状。这个王的位置，在后面的对攻中意义重大。","69":"▲6七金。抬起金，和5七的银并排，筑起防守的墙。","71":"▲7七桂。跳起桂马，准备参加进攻。","73":"▲6五歩。冲撞6筋的步，摇动后手阵地。","75":"▲5六歩。打步，巩固中央。","76":"△3六歩。后手挺进3筋的步，戳先手的马。","77":"▲同马。用马吃步。","78":"△5六歩。后手用步吃步，逼近中央。","79":"▲同银。先手用银吃回。","80":"△5五歩。后手打步，堵住银的前方。","81":"▲6五银。银吃掉6五的步，从侧面接近后手阵地。","82":"△6四歩。后手打步追赶银。","83":"▲5四银。银吃掉5四的银，消掉后手一个防守棋子。","84":"△同金。后手用金吃回。","85":"▲6五歩。再打一步，继续从6筋进攻。","86":"△3五歩。后手打步追赶先手的马。","87":"▲3七马。马回到3七。这是守护自己阵地的重要棋子，所以不勉强向前。","88":"△4四银。后手抬起银守护王。","89":"▲5六歩。打步，与后手5五的步相撞，想撬开中央。","91":"▲6四歩。6五的步吃掉6四的步，先手的步攻进了后手阵地。","92":"△4六歩。后手挺进4筋的步反击。","95":"▲6三歩成。步升变为と金。と金走法和金一样，被吃掉时对方却只得到一枚步。","96":"△同金。后手用金吃掉と金。","97":"▲6六歩。打步，填补自己阵地的空隙。","98":"△3三桂。后手跳起桂马用于防守。","99":"▲6五银。打下手里的银，这只银瞄准5四的金。","100":"△6四歩。后手打步，想挡住银。","101":"▲5四银。银吃掉5四的金，后手王身边的守卫又少了一个。","102":"△同金。后手用金吃回。","103":"▲3四歩。打步，戳后手王的附近。","104":"△同玉。后手的王吃掉步，出到3四。王越来越往前了。","105":"▲3六歩。打步，压住后手王的前方。","106":"△4四银。后手打银守王。","107":"▲3九飞。先手又把飞车移回3筋。后手的王在3筋上，袖飞车又发挥作用了。","108":"△4三玉。后手的王退回4三。","109":"▲3五歩。3六的步吃掉3五的步，先手的步逼近后手的王。","110":"△3八歩。后手打步，攻击3九的飞车。","111":"▲3四金，将军。打下手里的金，把后手的王进一步赶开。","112":"△5三玉。后手的王逃到5三。","113":"▲5九飞。飞车被3筋的步攻击，躲到5九。","115":"▲2六马。马躲到2六。后手的银如果来到4六，就会攻击3七的马，看来是提前避开。","116":"△4六银。后手的银吃掉4六的步，接近先手阵地。","117":"▲3三金。金吃掉桂马。先手一个个削减后手阵地的棋子。","119":"▲3四金。金又回到3四，堵住王的逃路。","121":"▲7四桂。打下桂马，瞄准后手飞车所在的8二和6二。","122":"△4二飞。后手让飞车逃到4筋。","123":"▲4四歩。打步，把后手防守的金引出来。","124":"△同金。后手用金吃步。","125":"▲同金。先手用金吃金。","126":"△同飞。后手用飞车吃回。","127":"▲5六金。金吃掉5六的步。","128":"△同银。后手用银吃金。","129":"▲同飞。先手用飞车吃回银。交换继续，比赛进入了最后阶段。","130":"△5五银。后手打银追赶先手的飞车。","131":"▲5九飞。飞车退下。","132":"△5八歩。后手打步，再次追赶飞车。","133":"▲6九飞。飞车到6九。后手不停地用步追赶先手的飞车。","134":"△5四玉。后手的王一直出到5四。王在棋盘中央，身边守卫少，容易成为目标。","135":"▲3六马，将军。马走到3六，沿经过4五的斜线将军5四的王。一直守护自己阵地的马，在这里加入了进攻。","136":"△4五金。后手打金，挡住马的斜线。","137":"▲6五金，将军。打下金，从王的正旁边逼近。","138":"△同歩。后手用步吃金。","139":"▲同银，将军。7六的银吃掉那枚步将军。从中盘起一直守在王前的银，在这里加入了进攻。","140":"△4三玉。后手的王回到4三。","141":"▲4五马。马吃掉4五的金，先手不断吃掉后手王身边的棋子。","142":"△同飞。后手用飞车吃掉马。","143":"▲5四银，将军。关根看出王已经无法逃脱，于是在这里认输。阪田143手获胜。他用袖飞车从3筋进攻，在漫长的中盘一边用马守护自己的阵地，一边一点点削减对方的棋子，最后抓住了走到前面的后手的王。这是一盘很像自学成才的阪田那样顽强的对局。阪田去世后，被追赠了名人和王将的称号。"}}};
